use std::fs;
use std::io::{self, Read, Write};
use settings::Settings;

fn print_help() {
    eprintln!("svgbob 0.7.6");
    eprintln!("SvgBobRus is an ascii to svg converter");
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    svgbob [FLAGS] [OPTIONS] [input] [SUBCOMMAND]");
    eprintln!();
    eprintln!("FLAGS:");
    eprintln!("    -h, --help       Prints help information");
    eprintln!("    -s               parse an inline string");
    eprintln!("    -V, --version    Prints version information");
    eprintln!();
    eprintln!("OPTIONS:");
    eprintln!("        --background <background>        backdrop background will be filled with this color (default: 'white')");
    eprintln!("        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')");
    eprintln!("        --font-family <font-family>      text will be rendered with this font (default: 'arial')");
    eprintln!("        --font-size <font-size>          text will be rendered with this font size (default: 14)");
    eprintln!("    -o, --output <output>                where to write svg output [default: STDOUT]");
