    eprintln!("                                         (default: 1)");
    eprintln!("        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')");
    eprintln!("        --stroke-width <stroke-width>    stroke width for all lines (default: 2)");
    eprintln!();
    eprintln!("ARGS:");
    eprintln!("    <input>    svgbob text file or inline string to parse [default: STDIN]");
    eprintln!();
    eprintln!("SUBCOMMANDS:");
    eprintln!("    build    Batch convert files to svg.");
    eprintln!("    help     Prints this message or the help of the given subcommand(s)");
}

fn print_version() {
    println!("svgbob 0.7.6");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut settings = Settings::default();
    let mut input_arg: Option<String> = None;
