        match args[1].as_str() {
            "build" => {
                build::run_build(&args[2..]);
                return;
            }
            "help" => {
                if args.len() > 2 {
                    match args[2].as_str() {
                        "build" => {
                            build::print_build_help();
                        }
                        _ => {
                            print_help();
                        }
                    }
                } else {
                    print_help();
                }
                return;
            }
            _ => {}
        }
    }

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                print_version();
                return;
            }
            "-s" => {
                inline = true;
            }
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    output_path = Some(args[i].clone());
                }
            }
            "--background" => {
                i += 1;
                if i < args.len() {
                    settings.background = args[i].clone();
                }
            }
            "--fill-color" => {
                i += 1;
                if i < args.len() {
                    settings.fill_color = args[i].clone();
                }
            }
            "--font-family" => {
                i += 1;
                if i < args.len() {
                    settings.font_family = args[i].clone();
                }
            }
            "--font-size" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.font_size = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument font-size: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
            "--scale" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.scale = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument scale: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
            "--stroke-color" => {
                i += 1;
                if i < args.len() {
                    settings.stroke_color = args[i].clone();
                }
            }
            "--stroke-width" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.stroke_width = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument stroke-width: {}", e);
                            std::process::exit(1);
                        }
                    }
