fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut settings = Settings::default();
    let mut input_arg: Option<String> = None;
    let mut output_path: Option<String> = None;
    let mut inline = false;
    let mut i = 1;

    // Check for subcommands first
    if args.len() > 1 {
        match args[1].as_str() {
            "build" => {
                build::run_build(&args[2..]);
                return;
            }
            "help" => {
                if args.len() > 2 {
                    match args[2].as_str() {
                        "build" => {
                            build::print_build_help();
                        }
                        _ => {
                            print_help();
                        }
                    }
                } else {
                    print_help();
                }
                return;
            }
            _ => {}
        }
    }

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                print_version();
                return;
            }
            "-s" => {
                inline = true;
            }
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    output_path = Some(args[i].clone());
                }
            }
            "--background" => {
                i += 1;
                if i < args.len() {
                    settings.background = args[i].clone();
                }
            }
            "--fill-color" => {
                i += 1;
                if i < args.len() {
                    settings.fill_color = args[i].clone();
                }
            }
            "--font-family" => {
                i += 1;
                if i < args.len() {
                    settings.font_family = args[i].clone();
                }
            }
            "--font-size" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.font_size = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument font-size: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
            "--scale" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.scale = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument scale: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
            "--stroke-color" => {
                i += 1;
                if i < args.len() {
                    settings.stroke_color = args[i].clone();
                }
            }
            "--stroke-width" => {
                i += 1;
                if i < args.len() {
                    match args[i].parse::<f64>() {
                        Ok(v) => settings.stroke_width = v,
                        Err(e) => {
                            eprintln!("Illegal value for argument stroke-width: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
            _ if arg.starts_with("--") => {
                eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
                eprintln!();
                eprintln!("USAGE:");
                eprintln!("    svgbob [FLAGS] [OPTIONS] [input] [SUBCOMMAND]");
                eprintln!();
                eprintln!("For more information try --help");
                std::process::exit(1);
            }
            _ => {
                input_arg = Some(arg.clone());
                i += 1;
                // Check for unexpected extra arguments
                if i < args.len() {
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", args[i]);
                    eprintln!();
                    if inline {
                        eprintln!("USAGE:");
                        eprintln!("    svgbob -s");
                    } else {
                        eprintln!("USAGE:");
                        eprintln!("    svgbob [input]");
                    }
                    eprintln!();
                    eprintln!("For more information try --help");
                    std::process::exit(1);
                }
                break;
            }
        }
        i += 1;
    }

    // Read input
    let content = if inline {
        match input_arg {
            Some(s) => s,
            None => {
                // This should panic like the original
                panic!("called `Option::unwrap()` on a `None` value");
            }
        }
    } else {
        match input_arg {
            Some(path) => {
                match fs::read_to_string(&path) {
                    Ok(content) => content,
                    Err(e) => {
                        eprintln!("Failed to open input file {}: {}", path, e);
                        std::process::exit(1);
                    }
                }
            }
            None => {
                let mut content = String::new();
                io::stdin().read_to_string(&mut content).unwrap();
                content
            }
        }
    };

    let svg = render::to_svg(&content, &settings);

    match output_path {
        Some(path) => {
            fs::write(&path, svg).unwrap();
        }
        None => {
            print!("{}", svg);
        }
    }
}
