use crate::settings::Settings;

// Cell dimensions (before scaling)
const W: f64 = 8.0;  // cell width
const H: f64 = 16.0; // cell height

#[derive(Debug, Clone)]
struct Point {
    x: f64,
    y: f64,
}

impl PartialEq for Point {
    fn eq(&self, other: &Self) -> bool {
        (self.x - other.x).abs() < 0.001 && (self.y - other.y).abs() < 0.001
    }
}

impl Point {
    fn new(x: f64, y: f64) -> Self {
        Point { x, y }
    }
}

#[derive(Debug, Clone)]
enum Fragment {
    Line(Point, Point, LineClass),
    Arc(f64, f64, f64, f64, bool, ArcClass), // x1,y1 -> x2,y2, sweep
    Circle(f64, f64, f64, CircleClass),
    Polygon(Vec<(f64, f64)>, PolygonClass),
    Text(f64, f64, String),
    Rect(f64, f64, f64, f64, f64), // x,y,w,h,rx
}

#[derive(Debug, Clone, PartialEq)]
enum LineClass {
    Solid,
    Broken,
    SolidEndMarkedOpenCircle,
    SolidEndMarkedCircle,
    SolidEndMarkedBigOpenCircle,
}

#[derive(Debug, Clone)]
enum ArcClass {
    Nofill,
}

#[derive(Debug, Clone)]
enum CircleClass {
    Nofill,
}

#[derive(Debug, Clone)]
enum PolygonClass {
    Filled,
}

impl Fragment {
    fn is_line(&self) -> bool {
        matches!(self, Fragment::Line(..))
    }

    fn endpoints(&self) -> Option<(Point, Point)> {
        match self {
            Fragment::Line(p1, p2, _) => Some((p1.clone(), p2.clone())),
            _ => None,
        }
    }

    fn shares_endpoint(&self, other: &Fragment) -> bool {
        if let (Some((p1, p2)), Some((q1, q2))) = (self.endpoints(), other.endpoints()) {
            p1 == q1 || p1 == q2 || p2 == q1 || p2 == q2
        } else if let Some((p1, p2)) = self.endpoints() {
            match other {
                Fragment::Polygon(_, _) => {
                    // Check if polygon shares a point
                    false
                }
                _ => false,
            }
        } else {
            false
        }
    }
}

// Grid helper functions
fn cell_x(col: i32) -> f64 { col as f64 * W }
fn cell_y(row: i32) -> f64 { row as f64 * H }
fn cell_cx(col: i32) -> f64 { col as f64 * W + W / 2.0 }
fn cell_cy(row: i32) -> f64 { row as f64 * H + H / 2.0 }

struct Grid {
    rows: Vec<Vec<char>>,
    num_rows: usize,
    num_cols: usize,
}

impl Grid {
    fn new(text: &str) -> Self {
        let lines: Vec<&str> = text.split('\n').collect();

        // Strip trailing empty lines
        let mut last_non_empty = 0;
        for (i, line) in lines.iter().enumerate() {
            if !line.trim().is_empty() || !line.is_empty() {
                // Check if line has any content (even spaces)
                if line.chars().any(|c| c != ' ') {
                    last_non_empty = i + 1;
                } else if last_non_empty > 0 {
                    // Count empty/whitespace lines after content
                    // Actually we need to find the last non-trailing-empty line
                }
            }
        }

        // Actually strip trailing blank/whitespace lines properly
        let mut end = lines.len();
        while end > 0 && lines[end-1].chars().all(|c| c == ' ' || c == '\t') {
            end -= 1;
        }
        let lines = &lines[..end];

        let num_rows = lines.len();

        let rows: Vec<Vec<char>> = lines.iter().map(|line| {
            // Strip trailing spaces
            let s = line.trim_end_matches(' ');
            s.chars().collect()
        }).collect();

        let num_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

        Grid { rows, num_rows, num_cols }
    }

    fn get(&self, col: i32, row: i32) -> char {
        if row < 0 || col < 0 || row as usize >= self.num_rows {
            return ' ';
        }
        let row = row as usize;
        let col = col as usize;
        if col >= self.rows[row].len() {
            ' '
        } else {
            self.rows[row][col]
        }
    }

    fn svg_width(&self) -> f64 {
        (self.num_cols + 2) as f64 * W
    }

    fn svg_height(&self) -> f64 {
        (self.num_rows + 1) as f64 * H
    }
}

// Character classification
fn is_drawing(c: char) -> bool {
    matches!(c, '-' | '=' | '~' | '|' | ':' | '/' | '\\' | '_' |
              '+' | '.' | '\'' | '`' | ',' | '*' | 'o' | 'O' |
              '>' | '<' | '^' | 'v' | '(' | ')')
}

fn is_horizontal_line(c: char) -> bool {
    matches!(c, '-' | '=' | '~')
}

fn is_vertical_line(c: char) -> bool {
    c == '|'
}

fn is_junction(c: char) -> bool {
    matches!(c, '+' | '.' | '\'' | '`' | ',')
}

fn connects_left(c: char) -> bool {
    matches!(c, '-' | '=' | '~' | '+' | '.' | '\'' | '`' | ',' | '<' | '>' | 'o' | 'O' | '*')
}

fn connects_right(c: char) -> bool {
    matches!(c, '-' | '=' | '~' | '+' | '.' | '\'' | '`' | ',' | '<' | '>' | 'o' | 'O' | '*')
}

fn connects_up(c: char) -> bool {
    matches!(c, '|' | ':' | '+' | '.' | '\'' | '`' | ',' | '^' | 'v' | 'o' | 'O' | '*')
}

fn connects_down(c: char) -> bool {
    matches!(c, '|' | ':' | '+' | '.' | '\'' | '`' | ',' | '^' | 'v' | 'o' | 'O' | '*')
}

// Check if character connects in diagonal directions
fn connects_upper_left(c: char) -> bool {
    c == '\\'
}

fn connects_lower_right(c: char) -> bool {
    c == '\\'
}

fn connects_upper_right(c: char) -> bool {
    c == '/'
}

fn connects_lower_left(c: char) -> bool {
    c == '/'
}

pub fn to_svg(text: &str, settings: &Settings) -> String {
    let grid = Grid::new(text);
    let fragments = process_grid(&grid);
    let scaled_frags = scale_fragments(fragments, settings.scale);

    let width = grid.svg_width() * settings.scale;
    let height = grid.svg_height() * settings.scale;

    let mut svg = String::new();

    // SVG header
    svg.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",
        format_num(width), format_num(height)));

    // Style
    svg.push_str(&generate_style(settings));

    // Defs
    svg.push_str(&generate_defs(settings));

    // Backdrop
    svg.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
        format_num(width), format_num(height)));

    // Render fragments
    let groups = group_fragments(scaled_frags);
    for group in groups {
        if group.len() == 1 {
            svg.push_str(&render_fragment(&group[0]));
        } else {
            svg.push_str("  <g>\n");
            for frag in &group {
                let s = render_fragment(frag);
                // Indent
                for line in s.lines() {
                    svg.push_str("  ");
                    svg.push_str(line);
                    svg.push('\n');
                }
            }
            svg.push_str("  </g>\n");
        }
    }

    svg.push_str("</svg>\n");
    svg
}

fn format_num(n: f64) -> String {
    if n == n.floor() && n.abs() < 1e10 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn process_grid(grid: &Grid) -> Vec<Fragment> {
    let mut fragments = Vec::new();

    // First pass: collect all text runs and drawing chars
    // We need to identify:
    // 1. Consecutive drawing chars that form lines
    // 2. Text runs (consecutive non-drawing non-space chars)

    // Process each row
    for row in 0..grid.num_rows as i32 {
        let mut col = 0i32;
        while col < grid.num_cols as i32 + 2 {
            let c = grid.get(col, row);

            if c == ' ' || c == '\0' {
                col += 1;
                continue;
            }

            if is_drawing(c) {
                // Generate fragments for this drawing character
                let frags = generate_cell_fragments(grid, col, row, c);
                fragments.extend(frags);
                col += 1;
            } else {
                // Start of text run
                let start_col = col;
                let mut text = String::new();
                while col < grid.num_cols as i32 + 2 {
                    let ch = grid.get(col, row);
                    if ch == ' ' || is_drawing(ch) || ch == '\0' {
                        break;
                    }
                    text.push_str(&html_escape(ch));
                    col += 1;
                }
                if !text.is_empty() {
                    let x = cell_x(start_col) + 2.0;
                    let y = cell_y(row) + H * 0.75;
                    fragments.push(Fragment::Text(x, y, text));
                }
            }
        }
    }

    // Now process diagonal lines
    // (already handled in generate_cell_fragments)

    // Merge collinear lines
    let fragments = merge_lines(fragments);

    // Detect rectangles
    detect_rectangles(fragments)
}

fn html_escape(c: char) -> String {
    match c {
        '<' => "&lt;".to_string(),
        '>' => "&gt;".to_string(),
        '&' => "&amp;".to_string(),
        '\'' => "&#39;".to_string(),
        '"' => "&quot;".to_string(),
        _ => c.to_string(),
    }
}

fn generate_cell_fragments(grid: &Grid, col: i32, row: i32, c: char) -> Vec<Fragment> {
    let mut frags = Vec::new();

    let left = grid.get(col - 1, row);
    let right = grid.get(col + 1, row);
    let above = grid.get(col, row - 1);
    let below = grid.get(col, row + 1);
    let ul = grid.get(col - 1, row - 1); // upper-left diagonal
    let ur = grid.get(col + 1, row - 1); // upper-right diagonal  
    let ll = grid.get(col - 1, row + 1); // lower-left diagonal
    let lr = grid.get(col + 1, row + 1); // lower-right diagonal

    let has_left = connects_right(left);
    let has_right = connects_left(right);
    let has_above = connects_down(above);
    let has_below = connects_up(below);

    match c {
        '-' => {
            // Horizontal line from left edge to right edge
            frags.push(Fragment::Line(
                Point::new(cell_x(col), cell_cy(row)),
                Point::new(cell_x(col + 1), cell_cy(row)),
                LineClass::Solid,
            ));
        }
        '=' => {
            // Double horizontal lines
            let y1 = cell_cy(row) - 2.0;
            let y2 = cell_cy(row) + 2.0;
            frags.push(Fragment::Line(
                Point::new(cell_x(col), y1),
                Point::new(cell_x(col + 1), y1),
                LineClass::Solid,
            ));
            frags.push(Fragment::Line(
                Point::new(cell_x(col), y2),
                Point::new(cell_x(col + 1), y2),
                LineClass::Solid,
            ));
        }
        '~' => {
            // Broken horizontal line
            frags.push(Fragment::Line(
                Point::new(cell_x(col), cell_cy(row)),
                Point::new(cell_x(col + 1), cell_cy(row)),
                LineClass::Broken,
            ));
        }
        '|' => {
            // Vertical line from top to bottom
            frags.push(Fragment::Line(
                Point::new(cell_cx(col), cell_y(row)),
                Point::new(cell_cx(col), cell_y(row + 1)),
                LineClass::Solid,
            ));
        }
        ':' => {
            // Broken vertical line (only when stacked)
            let above_colon = above == ':';
            let below_colon = below == ':';
            if above_colon || below_colon {
                frags.push(Fragment::Line(
                    Point::new(cell_cx(col), cell_y(row)),
                    Point::new(cell_cx(col), cell_y(row + 1)),
                    LineClass::Broken,
                ));
            } else {
                // Text
                let x = cell_x(col) + 2.0;
                let y = cell_y(row) + H * 0.75;
                frags.push(Fragment::Text(x, y, ":".to_string()));
            }
        }
        '/' => {
            // Diagonal from bottom-left to top-right
            frags.push(Fragment::Line(
                Point::new(cell_x(col + 1), cell_y(row)),
                Point::new(cell_x(col), cell_y(row + 1)),
                LineClass::Solid,
            ));
        }
        '\\' => {
            // Diagonal from top-left to bottom-right
            frags.push(Fragment::Line(
                Point::new(cell_x(col), cell_y(row)),
                Point::new(cell_x(col + 1), cell_y(row + 1)),
                LineClass::Solid,
            ));
        }
        '_' => {
            // Bottom horizontal line
            frags.push(Fragment::Line(
                Point::new(cell_x(col), cell_y(row + 1)),
                Point::new(cell_x(col + 1), cell_y(row + 1)),
                LineClass::Solid,
            ));
        }
        '+' => {
            // Junction - connects in whatever directions have adjacent drawing chars
            if has_left || has_right {
                // Horizontal connection through center
                let x1 = if has_left { cell_cx(col) } else { cell_cx(col) };
                let x2 = if has_right { cell_cx(col) } else { cell_cx(col) };
                if has_left {
                    frags.push(Fragment::Line(
                        Point::new(cell_cx(col), cell_cy(row)),
                        Point::new(cell_cx(col), cell_cy(row)), // will be merged
                        LineClass::Solid,
                    ));
                }
                // The center point will be used as merge point
            }
            // Generate a center point fragment
