fn group_fragments(fragments: Vec<Fragment>) -> Vec<Vec<Fragment>> {
    // Group connected fragments
    let mut groups: Vec<Vec<Fragment>> = Vec::new();

    for frag in fragments {
        // Check if this fragment connects to any existing group
        let mut found = false;
        for group in &mut groups {
            let connects = group.iter().any(|g| shares_endpoint(g, &frag));
            if connects {
                group.push(frag.clone());
                found = true;
                break;
            }
        }
        if !found {
            groups.push(vec![frag]);
        }
    }

    // Merge groups that now connect
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let connects = groups[i].iter().any(|f1| {
                    groups[j].iter().any(|f2| shares_endpoint(f1, f2))
                });
                if connects {
                    let g = groups.remove(j);
                    groups[i].extend(g);
                    changed = true;
                } else {
                    j += 1;
                }
            }
            i += 1;
        }
    }

    groups
