        }
    }

    // Merge groups that now connect
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let connects = groups[i].iter().any(|f1| {
