    fragments // TODO: implement rectangle detection
}

fn scale_fragments(fragments: Vec<Fragment>, scale: f64) -> Vec<Fragment> {
    if scale == 1.0 {
        return fragments;
    }
    fragments.into_iter().map(|f| scale_fragment(f, scale)).collect()
}

fn scale_fragment(f: Fragment, scale: f64) -> Fragment {
    match f {
        Fragment::Line(p1, p2, class) => Fragment::Line(
            Point::new(p1.x * scale, p1.y * scale),
            Point::new(p2.x * scale, p2.y * scale),
            class,
        ),
        Fragment::Text(x, y, s) => Fragment::Text(x * scale, y * scale, s),
        Fragment::Rect(x, y, w, h, rx) => Fragment::Rect(x*scale, y*scale, w*scale, h*scale, rx*scale),
        Fragment::Circle(cx, cy, r, class) => Fragment::Circle(cx*scale, cy*scale, r*scale, class),
        _ => f,
    }
}

fn group_fragments(fragments: Vec<Fragment>) -> Vec<Vec<Fragment>> {
    // Group connected fragments
    let mut groups: Vec<Vec<Fragment>> = Vec::new();

    for frag in fragments {
        // Check if this fragment connects to any existing group
        let mut found = false;
        for group in &mut groups {
            let connects = group.iter().any(|g| shares_endpoint(g, &frag));
            if connects {
                group.push(frag.clone());
                found = true;
                break;
            }
        }
        if !found {
            groups.push(vec![frag]);
        }
    }

    // Merge groups that now connect
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let connects = groups[i].iter().any(|f1| {
                    groups[j].iter().any(|f2| shares_endpoint(f1, f2))
                });
                if connects {
                    let g = groups.remove(j);
                    groups[i].extend(g);
                    changed = true;
                } else {
                    j += 1;
                }
            }
            i += 1;
        }
    }

    groups
}

fn shares_endpoint(a: &Fragment, b: &Fragment) -> bool {
    if let (Some((p1, p2)), Some((q1, q2))) = (get_line_endpoints(a), get_line_endpoints(b)) {
        p1 == q1 || p1 == q2 || p2 == q1 || p2 == q2
    } else {
        false
    }
}

fn get_line_endpoints(f: &Fragment) -> Option<(Point, Point)> {
    match f {
        Fragment::Line(p1, p2, _) => Some((p1.clone(), p2.clone())),
        _ => None,
    }
}

fn render_fragment(f: &Fragment) -> String {
    match f {
        Fragment::Line(p1, p2, class) => {
            let class_str = match class {
                LineClass::Solid => "solid",
                LineClass::Broken => "broken",
                LineClass::SolidEndMarkedOpenCircle => "solid end_marked_open_circle",
                LineClass::SolidEndMarkedCircle => "solid end_marked_circle",
                LineClass::SolidEndMarkedBigOpenCircle => "solid end_marked_big_open_circle",
            };
            format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
                format_num(p1.x), format_num(p1.y),
                format_num(p2.x), format_num(p2.y),
                class_str)
        }
        Fragment::Arc(x1, y1, x2, y2, sweep, class) => {
            let class_str = match class {
                ArcClass::Nofill => "nofill",
            };
            let sf = if *sweep { 1 } else { 0 };
            format!("  <path d=\"M {},{} A 4,4 0,0,{} {},{}\" class=\"{}\"></path>\n",
                format_num(*x1), format_num(*y1), sf,
                format_num(*x2), format_num(*y2), class_str)
        }
        Fragment::Circle(cx, cy, r, class) => {
            let class_str = match class {
                CircleClass::Nofill => "nofill",
            };
            format!("  <circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}\"></circle>\n",
                format_num(*cx), format_num(*cy), format_num(*r), class_str)
        }
        Fragment::Polygon(points, class) => {
            let class_str = match class {
                PolygonClass::Filled => "filled",
            };
            let pts: Vec<String> = points.iter().map(|(x, y)| format!("{},{}", format_num(*x), format_num(*y))).collect();
            format!("  <polygon points=\"{}\" class=\"{}\"></polygon>\n",
                pts.join(" "), class_str)
        }
        Fragment::Text(x, y, s) => {
            format!("  <text x=\"{}\" y=\"{}\" >{}</text>\n",
                format_num(*x), format_num(*y), s)
        }
        Fragment::Rect(x, y, w, h, rx) => {
            format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"{}\"></rect>\n",
                format_num(*x), format_num(*y), format_num(*w), format_num(*h), format_num(*rx))
        }
    }
}

