    }
    if let Some(star_pos) = pattern.find('*') {
        let prefix = &pattern[..star_pos];
        let suffix = &pattern[star_pos+1..];
        name.starts_with(prefix) && name.ends_with(suffix) 
            && name.len() >= prefix.len() + suffix.len()
    } else {
        name == pattern
    }
}
