struct Grid {
    rows: Vec<Vec<char>>,
    num_rows: usize,
    num_cols: usize,
}

impl Grid {
    fn new(text: &str) -> Self {
        let raw_lines: Vec<&str> = text.split('\n').collect();

        // Strip trailing blank lines (lines that are empty or only whitespace)
        let mut end = raw_lines.len();
        while end > 0 && raw_lines[end-1].chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            end -= 1;
        }
        let lines = &raw_lines[..end];

        let rows: Vec<Vec<char>> = lines.iter().map(|line| {
            // Strip trailing spaces from each row
            let s = line.trim_end_matches(|c| c == ' ' || c == '\r');
            s.chars().collect()
        }).collect();

        let num_rows = rows.len();
        let num_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);

        Grid { rows, num_rows, num_cols }
    }

    fn get(&self, col: i32, row: i32) -> char {
        if row < 0 || col < 0 { return ' '; }
        let r = row as usize;
        let c = col as usize;
        if r >= self.num_rows { return ' '; }
        if c >= self.rows[r].len() { return ' '; }
        self.rows[r][c]
    }
}

// x/y helpers
fn cx(col: i32) -> f64 { col as f64 * W + W/2.0 }  // cell center x
fn cy(row: i32) -> f64 { row as f64 * H + H/2.0 }  // cell center y
fn lx(col: i32) -> f64 { col as f64 * W }           // cell left x
fn rx(col: i32) -> f64 { (col+1) as f64 * W }       // cell right x
fn ty(row: i32) -> f64 { row as f64 * H }           // cell top y
fn by(row: i32) -> f64 { (row+1) as f64 * H }       // cell bottom y

#[derive(Debug, Clone)]
enum Element {
    Line(f64, f64, f64, f64, &'static str),  // x1,y1,x2,y2,class
    Path(String, &'static str),               // d, class
    Circle(f64, f64, f64, &'static str),      // cx,cy,r,class
    Polygon(Vec<(f64,f64)>, &'static str),    // points, class
    Text(f64, f64, String),                   // x,y,content
    Rect(f64, f64, f64, f64, f64, &'static str), // x,y,w,h,rx,class
}

impl Element {
    fn endpoints(&self) -> Vec<(f64,f64)> {
        match self {
            Element::Line(x1,y1,x2,y2,_) => vec![(*x1,*y1),(*x2,*y2)],
            Element::Polygon(pts,_) => {
                if let (Some(p0),Some(pn)) = (pts.first(), pts.last()) {
                    vec![*p0, *pn]
                } else { vec![] }
            }
            _ => vec![],
        }
    }

    fn shares_point(&self, other: &Element) -> bool {
        let eps = |a: f64, b: f64| (a-b).abs() < 0.1;
        let pt_eq = |(ax,ay): &(f64,f64), (bx,by): &(f64,f64)| eps(*ax,*bx) && eps(*ay,*by);

        for p in self.endpoints() {
            for q in other.endpoints() {
                if pt_eq(&p, &q) { return true; }
            }
        }
        false
    }
}

fn process_grid(grid: &Grid) -> Vec<Element> {
