            let c = grid.get(col, row);
            match c {
                ' ' => { col += 1; }
                '-' | '=' | '~' => {
                    // Scan horizontal segment
                    let start_col = col;
                    while col < grid.num_cols as i32 + 1 {
                        let ch = grid.get(col, row);
                        if ch == '-' || ch == '=' || ch == '~' { col += 1; }
                        else if is_h_connector(ch) && h_connects_both(grid, col, row) { col += 1; }
                        else { break; }
                    }
                    let end_col = col - 1;
                    // Generate line segment for this horizontal run
                    let frags = gen_horizontal_segment(grid, start_col, end_col, row);
                    elements.extend(frags);
