                '|' | ':' => {
                    // Vertical line segment - just generate for this single cell
                    // (vertical merging happens implicitly through endpoint sharing)
                    let is_broken = c == ':';
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = connects_vertically(above);
                    let has_below = connects_vertically(below);

                    if c == ':' && !has_above && !has_below {
                        // ':' alone is text
                        elements.push(Element::Text(lx(col)+2.0, cy(row)+H*0.25, ":".to_string()));
                    } else if c == ':' {
                        let class = "broken";
                        elements.push(Element::Line(cx(col), ty(row), cx(col), by(row), class));
                    } else {
                        let class = "solid";
                        elements.push(Element::Line(cx(col), ty(row), cx(col), by(row), class));
                    }
                    col += 1;
                }
                '/' => {
                    elements.push(Element::Line(rx(col), ty(row), lx(col), by(row), "solid"));
                    col += 1;
                }
                '\\' => {
                    elements.push(Element::Line(lx(col), ty(row), rx(col), by(row), "solid"));
                    col += 1;
                }
                '_' => {
                    // Bottom horizontal line
                    // Scan consecutive underscores
                    let start_col = col;
                    while col < grid.num_cols as i32 + 1 && grid.get(col, row) == '_' {
                        col += 1;
                    }
                    let end_col = col - 1;
                    elements.push(Element::Line(
                        lx(start_col), by(row),
                        rx(end_col), by(row),
