                        elements.push(Element::Line(cx(col), ty(row), lx(col), by(row), "solid"));
                        elements.push(Element::Line(cx(col), ty(row), rx(col), by(row), "solid"));
                    } else {
                        // text
                        elements.push(Element::Text(lx(col)+2.0, cy(row)+H*0.25, "^".to_string()));
                    }
                    col += 1;
                }
                'v' => {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = connects_vertically(above);
                    let has_below = connects_vertically(below);

                    if has_above {
                        // Arrowhead pointing down
                        elements.push(Element::Polygon(vec![
                            (lx(col), ty(row)+H*0.25),
                            (rx(col), ty(row)+H*0.25),
                            (cx(col), by(row)),
                        ], "filled"));
                    } else if has_below {
                        // Inverted V-fork upward
                        elements.push(Element::Line(lx(col), ty(row), cx(col), by(row), "solid"));
                        elements.push(Element::Line(rx(col), ty(row), cx(col), by(row), "solid"));
                    } else {
                        elements.push(Element::Text(lx(col)+2.0, cy(row)+H*0.25, "v".to_string()));
