                }
            }
            '.' | '\'' | '`' | ',' | '+' => {
                // Junction - handled by line generation
            }
            '-' => {} // handled by main line
            '=' => {} // handled by main line
            '~' => {} // handled by main line
            _ => {}
        }
        i += 1;
    }

    // Generate the main line(s)
    let class = if is_broken { "broken" } else { "solid" };

    // Find segments between special characters (o, *, O, >, <)
    let segments = get_line_segments(grid, start_col, end_col, row, x1, x2);

    if is_double {
        for (sx1, sx2) in &segments {
            elements.push(Element::Line(*sx1, cy(row)-2.0, *sx2, cy(row)-2.0, "solid"));
            elements.push(Element::Line(*sx1, cy(row)+2.0, *sx2, cy(row)+2.0, "solid"));
        }
    } else {
        for (sx1, sx2) in &segments {
            if (sx2 - sx1).abs() > 0.01 {
                elements.push(Element::Line(*sx1, cy(row), *sx2, cy(row), class));
            }
        }
    }

    // Handle corner arcs
    let sc = grid.get(start_col, row);
    let ec = grid.get(end_col, row);

    // Check if start_col has a vertical connection (corner arc)
    if is_corner_char(sc) {
        let above = grid.get(start_col, row-1);
        let below = grid.get(start_col, row+1);
        if connects_vertically(below) && !connects_vertically(above) {
            // Top-left corner: "." type
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(rx(start_col)), fmt(cy(row)),
                fmt(cx(start_col)), fmt(ty(row+1)-4.0));
            elements.push(Element::Path(d, "nofill"));
        } else if connects_vertically(above) && !connects_vertically(below) {
            // Bottom-left corner: "'" type  
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(cx(start_col)), fmt(cy(row)-4.0),
                fmt(rx(start_col)), fmt(cy(row)));
            elements.push(Element::Path(d, "nofill"));
        } else if connects_vertically(above) && connects_vertically(below) {
            // T-junction or pass-through (no arc needed)
        }
    }

    if is_corner_char(ec) && start_col != end_col {
        let above = grid.get(end_col, row-1);
        let below = grid.get(end_col, row+1);
        if connects_vertically(below) && !connects_vertically(above) {
            // Top-right corner
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(lx(end_col)), fmt(cy(row)),
                fmt(cx(end_col)), fmt(ty(row+1)-4.0));
            elements.push(Element::Path(d, "nofill"));
        } else if connects_vertically(above) && !connects_vertically(below) {
            // Bottom-right corner
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(cx(end_col)), fmt(cy(row)-4.0),
                fmt(lx(end_col)), fmt(cy(row)));
            elements.push(Element::Path(d, "nofill"));
        }
    }

    elements
}

fn is_corner_char(c: char) -> bool {
    matches!(c, '.' | '\'' | '`' | ',')
}

fn start_x(grid: &Grid, start_col: i32, _end_col: i32, row: i32) -> f64 {
    let c = grid.get(start_col, row);
    match c {
        '-' | '~' => lx(start_col),
        '=' => lx(start_col),
        '+' => cx(start_col),
        '.' | '\'' | '`' | ',' => {
            // Corner chars connect from inner edge
            let below = grid.get(start_col, row+1);
            let above = grid.get(start_col, row-1);
            if connects_vertically(below) || connects_vertically(above) {
                cx(start_col) // when acting as corner, contribute center
            } else {
                rx(start_col) // otherwise inner edge
            }
        }
        '>' | '<' => cx(start_col),
        'o' | 'O' => rx(start_col),
        '*' => lx(start_col),
        _ => lx(start_col),
    }
}

fn end_x(grid: &Grid, _start_col: i32, end_col: i32, row: i32) -> f64 {
    let c = grid.get(end_col, row);
    match c {
        '-' | '~' => rx(end_col),
        '=' => rx(end_col),
        '+' => cx(end_col),
        '.' | '\'' | '`' | ',' => {
            let below = grid.get(end_col, row+1);
            let above = grid.get(end_col, row-1);
            if connects_vertically(below) || connects_vertically(above) {
                cx(end_col)
            } else {
                lx(end_col)
            }
        }
        '>' | '<' => cx(end_col),
        'o' | 'O' => cx(end_col),
        '*' => cx(end_col),
        _ => rx(end_col),
    }
}

fn h_connects_left(grid: &Grid, col: i32, row: i32) -> bool {
    let left = grid.get(col-1, row);
    is_h_dash_compatible(left)
}

fn h_connects_right(grid: &Grid, col: i32, row: i32) -> bool {
    let right = grid.get(col+1, row);
    is_h_dash_compatible(right)
}

fn has_broken_chars(grid: &Grid, start: i32, end: i32, row: i32) -> bool {
    for col in start..=end {
        if grid.get(col, row) == '~' { return true; }
    }
    false
}

fn has_double_chars(grid: &Grid, start: i32, end: i32, row: i32) -> bool {
    // Only double if ALL non-connector chars are '='
    let mut all_equal = true;
    for col in start..=end {
        let c = grid.get(col, row);
        if c != '=' && is_h_dash_compatible(c) && !is_h_connector(c) {
            all_equal = false;
            break;
        }
    }
    all_equal && (start..=end).any(|col| grid.get(col, row) == '=')
}

fn get_line_segments(grid: &Grid, start: i32, end: i32, row: i32, x1: f64, x2: f64) -> Vec<(f64,f64)> {
    // Find contiguous segments avoiding special chars that break the line
    let mut segments = Vec::new();
    let mut seg_start = x1;
    let mut in_seg = true;

    for col in start..=end {
        let c = grid.get(col, row);
        match c {
            'o' | 'O' => {
                // Open circle: line goes up to center, then restarts after
                if in_seg && seg_start < cx(col) - 0.01 {
                    // Don't add line to circle center here - handled separately
                }
                // For 'o': right side line starts at rx(col)
                // For 'O': right side line starts at rx(col)
                if col < end {
                    seg_start = if c == 'o' { rx(col) } else { rx(col) };
                    in_seg = true;
                } else {
                    in_seg = false;
                }
            }
            '*' => {
                // Filled circle: right side starts at lx(col)
                if col < end {
                    seg_start = lx(col);
                    in_seg = true;
                } else {
                    in_seg = false;
                }
            }
            '>' | '<' => {
                // Arrow: segment breaks here
                if c == '>' {
                    if col == end {
                        // Arrow at end: segment ends at lx(col)
                        if in_seg {
                            segments.push((seg_start, lx(col)));
                        }
                        in_seg = false;
                    } else if col == start {
                        // Arrow at start: segment starts at rx(col)
                        seg_start = rx(col);
                        in_seg = true;
                    } else {
                        // Arrow in middle: segment ends at lx, restarts at rx
                        if in_seg {
                            segments.push((seg_start, lx(col)));
                        }
                        seg_start = rx(col);
                        in_seg = true;
                    }
                } else { // '<'
                    if col == start {
                        // Arrow at start: segment starts at rx(col)
                        seg_start = rx(col);
                        in_seg = true;
                    } else if col == end {
                        if in_seg {
                            segments.push((seg_start, rx(col)));
                        }
                        in_seg = false;
                    } else {
                        if in_seg {
                            segments.push((seg_start, rx(col)));
                        }
                        seg_start = lx(col);
                        in_seg = true;
                    }
                }
            }
            _ => {}
        }
    }

    if in_seg {
        segments.push((seg_start, x2));
    }

    segments
}

fn merge_vertical_lines(elements: Vec<Element>) -> Vec<Element> {
    // Merge adjacent vertical line segments that share endpoints
    let mut result: Vec<Element> = Vec::new();
    let mut merged = vec![false; elements.len()];

    for i in 0..elements.len() {
        if merged[i] { continue; }
        if let Element::Line(x1i, y1i, x2i, y2i, ci) = &elements[i] {
            // Check if this is vertical
            let eps = 0.001f64;
            if (x1i - x2i).abs() < eps {
                // Vertical line - try to merge with others
                let mut x = *x1i;
                let mut y_start = y1i.min(y2i);
                let mut y_end = y1i.max(y2i);
                let class = *ci;

                let mut changed = true;
                while changed {
                    changed = false;
                    for j in 0..elements.len() {
                        if merged[j] || i == j { continue; }
                        if let Element::Line(x1j, y1j, x2j, y2j, cj) = &elements[j] {
                            if (x1j - x).abs() < eps && (x2j - x).abs() < eps && *cj == class {
                                let ys = y1j.min(y2j);
                                let ye = y1j.max(y2j);
                                // Check if segments touch or overlap
                                if ys <= y_end + eps && ye >= y_start - eps {
                                    y_start = y_start.min(ys);
                                    y_end = y_end.max(ye);
                                    merged[j] = true;
                                    changed = true;
                                }
                            }
                        }
                    }
                }

                merged[i] = true;
                result.push(Element::Line(x, y_start, x, y_end, class));
                continue;
            }
        }
        result.push(elements[i].clone());
    }

    result
}

fn detect_rectangles(grid: &Grid, elements: Vec<Element>) -> Vec<Element> {
    // Try to find complete rectangles in the grid
    let mut rects: Vec<(i32,i32,i32,i32,f64)> = Vec::new(); // col1,row1,col2,row2,rx

    for r1 in 0..grid.num_rows as i32 {
        for c1 in 0..grid.num_cols as i32 {
            let tl = grid.get(c1, r1);
            if !is_top_left_corner(tl) { continue; }

            // Look for rectangles starting at (c1, r1)
            for r2 in (r1+1)..grid.num_rows as i32 {
                for c2 in (c1+1)..grid.num_cols as i32 {
                    let tr = grid.get(c2, r1);
                    let bl = grid.get(c1, r2);
                    let br = grid.get(c2, r2);

                    if !is_top_right_corner(tr) { continue; }
                    if !is_bottom_left_corner(bl) { continue; }
                    if !is_bottom_right_corner(br) { continue; }

                    // Check if corners are compatible (same type: sharp or rounded)
                    let rx_val = corner_rx(tl);
                    if corner_rx(tr) != rx_val { continue; }
                    if corner_rx(bl) != rx_val { continue; }
                    if corner_rx(br) != rx_val { continue; }

                    // Check top and bottom sides are filled with dashes
                    let top_ok = (c1+1..c2).all(|c| is_h_line(grid.get(c, r1)));
                    let bot_ok = (c1+1..c2).all(|c| is_h_line(grid.get(c, r2)));
                    if !top_ok || !bot_ok { continue; }

                    // Check left and right sides are filled with bars
                    let left_ok = (r1+1..r2).all(|r| grid.get(c1, r) == '|');
                    let right_ok = (r1+1..r2).all(|r| grid.get(c2, r) == '|');
                    if !left_ok || !right_ok { continue; }

                    rects.push((c1, r1, c2, r2, rx_val));
                }
            }
        }
    }

    if rects.is_empty() {
        return elements;
    }

    // For each detected rectangle, remove the corresponding line elements
    // and add a rect element
    let mut result = Vec::new();

    // Collect cells that are part of rectangles
    let mut rect_cells: std::collections::HashSet<(i32,i32)> = std::collections::HashSet::new();
    for &(c1, r1, c2, r2, _) in &rects {
        for c in c1..=c2 { 
            rect_cells.insert((c, r1));
            rect_cells.insert((c, r2));
        }
        for r in r1..=r2 {
            rect_cells.insert((c1, r));
            rect_cells.insert((c2, r));
        }
    }

    // Add rect elements
    for &(c1, r1, c2, r2, rx_val) in &rects {
        result.push(Element::Rect(
            cx(c1), cy(r1),
            (c2-c1) as f64 * W,
            (r2-r1) as f64 * H,
            rx_val,
            "solid nofill",
        ));
    }

    // Add all non-rect elements
    // We need to filter out elements that correspond to the rectangle borders
    for elem in elements {
        // Keep element if it doesn't overlap with a rectangle boundary
        if !is_rect_element(&elem, &rects) {
            result.push(elem);
        }
    }

    result
}

fn is_rect_element(elem: &Element, rects: &[(i32,i32,i32,i32,f64)]) -> bool {
    match elem {
        Element::Line(x1,y1,x2,y2,_) => {
            for &(c1,r1,c2,r2,_) in rects {
                let eps = 0.1;
                // Check if this line is on the border of the rect
                let lx1 = cx(c1); let rx2 = cx(c2);
                let ty1 = cy(r1); let by2 = cy(r2);

                // Top side horizontal
                if (y1-ty1).abs()<eps && (y2-ty1).abs()<eps {
                    if *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                }
                // Bottom side horizontal
                if (y1-by2).abs()<eps && (y2-by2).abs()<eps {
                    if *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                }
                // Left side vertical
                if (x1-lx1).abs()<eps && (x2-lx1).abs()<eps {
                    if *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
                }
                // Right side vertical
                if (x1-rx2).abs()<eps && (x2-rx2).abs()<eps {
                    if *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
                }
            }
            false
        }
        Element::Path(d, _) => {
            // Check if this path is a corner arc of a rect
            for &(c1,r1,c2,r2,rx_val) in rects {
                if rx_val > 0.0 {
                    // Rounded corners have arcs
                    // Check if path endpoints match corner arc positions
                    let corners = [
                        (cx(c1), cy(r1)), // top-left
                        (cx(c2), cy(r1)), // top-right
                        (cx(c1), cy(r2)), // bottom-left
                        (cx(c2), cy(r2)), // bottom-right
                    ];
                    for (ccx, ccy) in &corners {
                        if d.contains(&fmt(*ccx)) || d.contains(&fmt(*ccy)) {
                            return true;
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn is_top_left_corner(c: char) -> bool {
    matches!(c, '+' | '.' | ',' )
}

fn is_top_right_corner(c: char) -> bool {
    matches!(c, '+' | '.' | '`' )
}

fn is_bottom_left_corner(c: char) -> bool {
    matches!(c, '+' | '\'' | '`' )
}

fn is_bottom_right_corner(c: char) -> bool {
    matches!(c, '+' | '\'' | ',' )
}

fn corner_rx(c: char) -> f64 {
    match c {
        '+' => 0.0,
        _ => 4.0,
    }
}

fn is_h_line(c: char) -> bool {
    matches!(c, '-' | '=')
}

fn group_elements(elements: Vec<Element>) -> Vec<Vec<Element>> {
    // Group elements that share endpoints (connected components)
    let mut groups: Vec<Vec<Element>> = Vec::new();

    'outer: for elem in elements {
        // Text elements don't group
        if let Element::Text(..) = &elem {
            groups.push(vec![elem]);
            continue;
        }
        // Rect elements don't group
        if let Element::Rect(..) = &elem {
            groups.push(vec![elem]);
            continue;
        }

        for group in &mut groups {
            let connects = group.iter().any(|g| {
                if let Element::Text(..) = g { return false; }
                g.shares_point(&elem)
            });
            if connects {
                group.push(elem);
                continue 'outer;
            }
        }
        groups.push(vec![elem]);
    }

    // Merge groups that now share points
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let connects = groups[i].iter().any(|a| {
                    if let Element::Text(..) | Element::Rect(..) = a { return false; }
                    groups[j].iter().any(|b| {
                        if let Element::Text(..) | Element::Rect(..) = b { return false; }
                        a.shares_point(b)
                    })
                });
                if connects {
                    let g = groups.remove(j);
                    groups[i].extend(g);
                    changed = true;
                } else {
                    j += 1;
                }
            }
            i += 1;
        }
    }

    groups
}

fn render_element(elem: &Element, scale: f64) -> String {
    match elem {
        Element::Line(x1,y1,x2,y2,class) => {
            format!("  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
                fmt(x1*scale), fmt(y1*scale), fmt(x2*scale), fmt(y2*scale), class)
        }
        Element::Path(d, class) => {
            let scaled_d = scale_path_d(d, scale);
            format!("  <path d=\"{}\" class=\"{}\"></path>\n", scaled_d, class)
        }
        Element::Circle(ccx, ccy, r, class) => {
            format!("  <circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}\"></circle>\n",
                fmt(ccx*scale), fmt(ccy*scale), fmt(r*scale), class)
        }
        Element::Polygon(pts, class) => {
            let pts_str: Vec<String> = pts.iter()
                .map(|(x,y)| format!("{},{}", fmt(x*scale), fmt(y*scale)))
                .collect();
            format!("  <polygon points=\"{}\" class=\"{}\"></polygon>\n",
                pts_str.join(" "), class)
        }
        Element::Text(x,y,s) => {
            format!("  <text x=\"{}\" y=\"{}\" >{}</text>\n",
                fmt(x*scale), fmt(y*scale), s)
        }
        Element::Rect(x,y,w,h,rx,class) => {
            format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>\n",
                fmt(x*scale), fmt(y*scale), fmt(w*scale), fmt(h*scale), class, fmt(rx*scale))
        }
    }
}

fn scale_path_d(d: &str, scale: f64) -> String {
    if scale == 1.0 { return d.to_string(); }
    // Parse and scale the path
    // Format: "M x,y A rx,ry rot,laf,sf x2,y2"
    let mut result = String::new();
    let parts: Vec<&str> = d.split_whitespace().collect();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "M" => {
                result.push_str("M ");
                i += 1;
                if i < parts.len() {
                    result.push_str(&scale_point(parts[i], scale));
                    i += 1;
                }
            }
            "A" => {
                result.push_str(" A ");
                i += 1;
                // rx,ry
                if i < parts.len() {
                    result.push_str(&scale_pair(parts[i], scale));
                    i += 1;
                }
                // rotation,large-arc,sweep
                if i < parts.len() {
                    result.push(' ');
                    result.push_str(parts[i]);
                    i += 1;
                }
                // end point x,y
                if i < parts.len() {
                    result.push(' ');
                    result.push_str(&scale_point(parts[i], scale));
                    i += 1;
                }
            }
            _ => {
                result.push(' ');
                result.push_str(parts[i]);
                i += 1;
            }
        }
    }
    result.trim().to_string()
}

fn scale_point(s: &str, scale: f64) -> String {
    if let Some((xs, ys)) = s.split_once(',') {
        let x: f64 = xs.parse().unwrap_or(0.0);
        let y: f64 = ys.parse().unwrap_or(0.0);
        format!("{},{}", fmt(x*scale), fmt(y*scale))
    } else {
        s.to_string()
    }
}

fn scale_pair(s: &str, scale: f64) -> String {
    if let Some((xs, ys)) = s.split_once(',') {
        let x: f64 = xs.parse().unwrap_or(0.0);
        let y: f64 = ys.parse().unwrap_or(0.0);
        format!("{},{}", fmt(x*scale), fmt(y*scale))
    } else {
        s.to_string()
    }
}

fn html_escape(c: char) -> String {
    match c {
        '<' => "&lt;".to_string(),
        '>' => "&gt;".to_string(),
        '&' => "&amp;".to_string(),
        '\'' => "&#39;".to_string(),
        '"' => "&quot;".to_string(),
        _ => c.to_string(),
    }
}

