use crate::settings::Settings;

const W: f64 = 8.0;
const H: f64 = 16.0;

pub fn to_svg(text: &str, settings: &Settings) -> String {
    let grid = Grid::new(text);
    let scale = settings.scale;

    let width = (grid.num_cols + 1) as f64 * W * scale;
    let height = (grid.num_rows + 1) as f64 * H * scale;

    let mut svg = String::new();
    svg.push_str(&format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",
        fmt(width), fmt(height)
    ));
    svg.push_str(&generate_style(settings));
    svg.push_str(&generate_defs());
    svg.push_str(&format!(
        "  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
        fmt(width), fmt(height)
    ));

    let elems = render_grid(&grid);
    let groups = group_elements(elems);

    for group in &groups {
        if group.len() == 1 {
            svg.push_str(&render_elem(&group[0], scale));
        } else {
            svg.push_str("  <g>\n");
            for elem in group {
                let s = render_elem(elem, scale);
                for line in s.lines() {
                    svg.push_str("  ");
                    svg.push_str(line);
                    svg.push('\n');
                }
            }
            svg.push_str("  </g>\n");
        }
    }

    svg.push_str("</svg>\n");
    svg
}

fn fmt(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e10 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

// Grid: represents the text as a 2D array of chars
struct Grid {
    rows: Vec<Vec<char>>,
    num_rows: usize,
    num_cols: usize,
}

impl Grid {
    fn new(text: &str) -> Self {
        let raw_lines: Vec<&str> = text.split('\n').collect();
        let mut end = raw_lines.len();
        while end > 0 && raw_lines[end-1].chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            end -= 1;
        }
        let lines = &raw_lines[..end];
        let rows: Vec<Vec<char>> = lines.iter().map(|line| {
            let s = line.trim_end_matches(|c: char| c == ' ' || c == '\r');
            s.chars().collect()
        }).collect();
        let num_rows = rows.len();
        let num_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
        Grid { rows, num_rows, num_cols }
    }

    fn get(&self, col: i32, row: i32) -> char {
        if row < 0 || col < 0 { return ' '; }
        let r = row as usize; let c = col as usize;
        if r >= self.num_rows { return ' '; }
        if c >= self.rows[r].len() { return ' '; }
        self.rows[r][c]
    }
}

// Coordinate helpers
fn lx(c: i32) -> f64 { c as f64 * W }
fn rx(c: i32) -> f64 { (c+1) as f64 * W }
fn cx(c: i32) -> f64 { c as f64 * W + W/2.0 }
fn ty(r: i32) -> f64 { r as f64 * H }
fn by(r: i32) -> f64 { (r+1) as f64 * H }
fn cy(r: i32) -> f64 { r as f64 * H + H/2.0 }

// SVG elements
#[derive(Debug, Clone)]
enum Elem {
    Line(f64, f64, f64, f64, &'static str),
    Path(String, &'static str),
    Circle(f64, f64, f64, &'static str),
    Polygon(Vec<(f64,f64)>, &'static str),
    Text(f64, f64, String),
    Rect(f64, f64, f64, f64, f64, &'static str), // x,y,w,h,rx,class
}

impl Elem {
    fn endpoints(&self) -> Vec<(f64,f64)> {
        match self {
            Elem::Line(x1,y1,x2,y2,_) => vec![(*x1,*y1),(*x2,*y2)],
            Elem::Polygon(pts,_) => pts.iter().take(1).chain(pts.iter().last()).map(|&p|p).collect(),
            _ => vec![],
        }
    }

    fn shares_pt(&self, other: &Elem) -> bool {
        let eps = |a:f64,b:f64| (a-b).abs() < 0.1;
        let eq = |(ax,ay):(f64,f64),(bx,by):(f64,f64)| eps(ax,bx) && eps(ay,by);
        for p in self.endpoints() {
            for q in other.endpoints() {
                if eq(p,q) { return true; }
            }
        }
        false
    }
}

fn is_drawing(c: char) -> bool {
    matches!(c, '-'|'='|'~'|'|'|':'|'/'|'\\'|'_'|'+'|'.'|'\''|'`'|','|'*'|'o'|'O'|'>'|'<'|'^'|'v'|'('|')')
}

fn h_line(c: char) -> bool { matches!(c, '-'|'='|'~') }
fn v_connects(c: char) -> bool {
    matches!(c, '|'|':'|'+'|'.'|'\''|'`'|','|'^'|'v'|'o'|'O'|'*')
}
fn h_connects(c: char) -> bool {
    matches!(c, '-'|'='|'~'|'+'|'.'|'\''|'`'|','|'o'|'O'|'*'|'>'|'<')
}
fn is_corner(c: char) -> bool { matches!(c, '.'|'\''|'`'|',') }

fn render_grid(grid: &Grid) -> Vec<Elem> {
    let mut elems: Vec<Elem> = Vec::new();

    // Detect complete rectangles first
    let rects = find_rects(grid);

    // Process each row for horizontal elements
    for row in 0..grid.num_rows as i32 {
        let mut col = 0i32;
        while col <= grid.num_cols as i32 {
            let c = grid.get(col, row);

            if c == ' ' { col += 1; continue; }

            if is_drawing(c) {
                // Check if this is the start of a horizontal segment
                if h_line(c) || (h_connects(c) && {
                    let right = grid.get(col+1, row);
                    h_connects(right) || h_line(right)
                }) {
                    // Find the extent of this horizontal segment
                    let seg_start = col;
                    let mut seg_end = col;

                    // Find end of segment: chars that continue horizontal connection
                    let mut j = col;
                    while j <= grid.num_cols as i32 {
                        let ch = grid.get(j, row);
                        if h_line(ch) {
                            seg_end = j;
                            j += 1;
                        } else if h_connects(ch) {
                            // Check if this connector has horizontal connections on both sides
                            let left_ch = grid.get(j-1, row);
                            let right_ch = grid.get(j+1, row);
                            let left_ok = h_line(left_ch) || h_connects(left_ch);
                            let right_ok = h_line(right_ch) || h_connects(right_ch);
                            if j == seg_start { // at start: need right connection
                                if right_ok {
                                    seg_end = j;
                                    j += 1;
                                } else {
                                    break;
                                }
                            } else if left_ok && right_ok {
                                seg_end = j;
                                j += 1;
                            } else if left_ok && !right_ok {
                                seg_end = j;
                                j += 1;
                                break;
                            } else {
                                break;
                            }
                        } else {
                            break;
                        }
                    }

                    if seg_end >= seg_start {
                        let mut seg_elems = gen_h_segment(grid, seg_start, seg_end, row, &rects);
                        elems.append(&mut seg_elems);
                        col = seg_end + 1;
                        continue;
                    }
                }

                // Vertical line
                if c == '|' || c == ':' {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = v_connects(above) || above == '|' || above == ':';
                    let has_below = v_connects(below) || below == '|' || below == ':';
                    if c == ':' && !has_above && !has_below {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, ":".to_string()));
                    } else {
                        let class = if c == ':' { "broken" } else { "solid" };
                        elems.push(Elem::Line(cx(col), ty(row), cx(col), by(row), class));
                    }
                    col += 1;
                    continue;
                }

                // Diagonal /
                if c == '/' {
                    elems.push(Elem::Line(rx(col), ty(row), lx(col), by(row), "solid"));
                    col += 1;
                    continue;
                }

                // Diagonal \
                if c == '\\' {
                    elems.push(Elem::Line(lx(col), ty(row), rx(col), by(row), "solid"));
                    col += 1;
                    continue;
                }

                // Underscore
                if c == '_' {
                    let start = col;
                    while col <= grid.num_cols as i32 && grid.get(col, row) == '_' {
                        col += 1;
                    }
                    elems.push(Elem::Line(lx(start), by(row), lx(col), by(row), "solid"));
                    continue;
                }

                // ^ arrow
                if c == '^' {
                    let below = grid.get(col, row+1);
                    let above = grid.get(col, row-1);
                    let has_below = v_connects(below);
                    let has_above = v_connects(above);
                    if has_below {
                        elems.push(Elem::Polygon(vec![
                            (lx(col), ty(row)+H*0.75),
                            (cx(col), ty(row)),
                            (rx(col), ty(row)+H*0.75),
                        ], "filled"));
                    } else if has_above {
                        elems.push(Elem::Line(cx(col), ty(row), lx(col), by(row), "solid"));
                        elems.push(Elem::Line(cx(col), ty(row), rx(col), by(row), "solid"));
                    } else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "^".to_string()));
                    }
                    col += 1;
                    continue;
                }

                // v arrow
                if c == 'v' {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = v_connects(above);
                    let has_below = v_connects(below);
                    if has_above {
                        elems.push(Elem::Polygon(vec![
                            (lx(col), ty(row)+H*0.25),
                            (rx(col), ty(row)+H*0.25),
                            (cx(col), by(row)),
                        ], "filled"));
                    } else if has_below {
                        elems.push(Elem::Line(lx(col), ty(row), cx(col), by(row), "solid"));
                        elems.push(Elem::Line(rx(col), ty(row), cx(col), by(row), "solid"));
                    } else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "v".to_string()));
                    }
                    col += 1;
                    continue;
                }

                // ( arc or circle
                if c == '(' {
                    let next = grid.get(col+1, row);
                    if next == ')' {
                        elems.push(Elem::Circle(rx(col), cy(row), W/2.0, "nofill"));
                        col += 2;
                        continue;
                    } else {
                        let d = format!("M {},{} A 16,16 0,0,0 {},{}",
                            fmt(rx(col)), fmt(ty(row)), fmt(rx(col)), fmt(by(row)));
                        elems.push(Elem::Path(d, "nofill"));
                        col += 1;
                        continue;
                    }
                }

                // ) arc
                if c == ')' {
                    let d = format!("M {},{} A 16,16 0,0,1 {},{}",
                        fmt(lx(col)), fmt(ty(row)), fmt(lx(col)), fmt(by(row)));
                    elems.push(Elem::Path(d, "nofill"));
                    col += 1;
                    continue;
                }

                // Other drawing chars that aren't part of a horizontal segment:
                // +, ., ', `, ,, *, o, O  -> only rendered when they're part of a segment
                // If we get here, they're isolated drawing chars -> render as text or skip
                if matches!(c, '+'|'.'|'\''|'`'|','|'*'|'o'|'O') {
                    // These are only drawing in context - as standalone they're text (or skip for +)
                    if c != '+' {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, html_escape_str(c)));
                    }
                    col += 1;
                    continue;
                }

                // > and < - isolated arrows
                if c == '>' {
                    let left = grid.get(col-1, row);
                    let right = grid.get(col+1, row);
                    if h_connects(left) { /* will be handled by horizontal segment */ }
                    else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "&gt;".to_string()));
                    }
                    col += 1;
                    continue;
                }
                if c == '<' {
                    elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "&lt;".to_string()));
                    col += 1;
                    continue;
                }
            }

            // Text character - scan a run
            if !is_drawing(c) && c != ' ' {
                let start_col = col;
                let mut text = String::new();
                while col <= grid.num_cols as i32 {
                    let ch = grid.get(col, row);
                    if ch == ' ' || is_drawing(ch) { break; }
                    text.push_str(&html_escape_ch(ch));
                    col += 1;
                }
                if !text.is_empty() {
                    elems.push(Elem::Text(lx(start_col)+2.0, cy(row)+4.0, text));
                }
                continue;
            }

            col += 1;
        }
    }

    // Merge vertical lines
    let elems = merge_vert(elems);

    // Add rect elements for detected rectangles (replacing the individual lines)
    add_rects(grid, elems, &rects)
}

fn gen_h_segment(grid: &Grid, start: i32, end: i32, row: i32, rects: &[(i32,i32,i32,i32,f64)]) -> Vec<Elem> {
    let mut result = Vec::new();

    // Check if this segment is part of a rectangle boundary
    if is_rect_h_side(start, end, row, rects) {
        return result; // Skip - handled by rect element
    }

    let sc = grid.get(start, row);
    let ec = grid.get(end, row);

    // Determine line type
    let is_broken = (start..=end).any(|c| grid.get(c, row) == '~');
    let is_double = !is_broken && (start..=end).all(|c| {
        let ch = grid.get(c, row);
        ch == '=' || is_corner(ch) || ch == '+'
    }) && (start..=end).any(|c| grid.get(c, row) == '=');

    let line_class: &'static str = if is_broken { "broken" } else { "solid" };

    // Generate corner arcs if needed
    if is_corner(sc) {
        let below = grid.get(start, row+1);
        let above = grid.get(start, row-1);
        let vb = v_connects(below);
        let va = v_connects(above);
        if vb && !va {
            // Top-left corner arc
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(rx(start)), fmt(cy(row)),
                fmt(cx(start)), fmt(ty(row+1)-4.0));
            result.push(Elem::Path(d, "nofill"));
        } else if va && !vb {
            // Bottom-left corner arc
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(cx(start)), fmt(cy(row)-4.0),
                fmt(rx(start)), fmt(cy(row)));
            result.push(Elem::Path(d, "nofill"));
        }
    }

    if is_corner(ec) && start != end {
        let below = grid.get(end, row+1);
        let above = grid.get(end, row-1);
        let vb = v_connects(below);
        let va = v_connects(above);
        if vb && !va {
            // Top-right corner arc
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(lx(end)), fmt(cy(row)),
                fmt(cx(end)), fmt(ty(row+1)-4.0));
            result.push(Elem::Path(d, "nofill"));
        } else if va && !vb {
            // Bottom-right corner arc
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(cx(end)), fmt(cy(row)-4.0),
                fmt(lx(end)), fmt(cy(row)));
            result.push(Elem::Path(d, "nofill"));
        }
    }

    // Process the segment to generate lines and markers
    // We iterate through the segment, building line segments split by special chars

    let x_start = seg_start_x(grid, start, row);
    let x_end = seg_end_x(grid, start, end, row);

    // Collect "break points" from special chars
    struct Segment {
        x1: f64, x2: f64,
        class: &'static str,
    }

    let mut segments: Vec<(f64, f64, &'static str)> = Vec::new();
    let mut cur_x = x_start;

    let mut i = start;
    while i <= end {
        let c = grid.get(i, row);
        match c {
            'o' | 'O' => {
                let marker = if c == 'o' { "solid end_marked_open_circle" } else { "solid end_marked_big_open_circle" };
                if i == start {
                    // At start: line from (rx(start+1)) backwards to cx(start) with marker
                    // Also: main line from rx(start+1) forward
                    let x_anchor = rx(start+1); // right edge of first dash
                    // Circle line (reversed)
                    result.push(Elem::Line(x_anchor, cy(row), cx(start), cy(row), marker));
                    cur_x = x_anchor;
                } else {
                    // Marker at this position: finish left segment with marker
                    result.push(Elem::Line(cur_x, cy(row), cx(i), cy(row), marker));
                    cur_x = rx(i); // next segment starts after the circle cell
                }
            }
            '*' => {
                if i == start {
                    // Zero-length circle marker at start
                    result.push(Elem::Line(cx(start), cy(row), cx(start), cy(row), "solid end_marked_circle"));
                    cur_x = rx(start); // actual line starts from right of star cell? No, lx(start+1)
                    cur_x = lx(start+1); // line starts from left of next char... wait
                    // Actually for "*---": main line from lx(start+1)=lx(1)=8 to end
                    // But for "-*-": main line from lx(star)=lx(1)=8 to end
                    // So main line starts at lx(i) = star's left edge
                    cur_x = lx(i); // will be overwritten below
                    // The zero-length marker is at cx(i), main line from lx(i+1)? No...
                    // Let me re-examine:
                    // "*---": main from x=8=lx(1), but we want it to start at lx(0+1)=lx(1)=8 ✓
                    // actually rx(i) = rx(0) = 8 = lx(1) ✓
                    cur_x = rx(i);
                } else {
                    // In middle or at end
                    result.push(Elem::Line(cur_x, cy(row), cx(i), cy(row), "solid end_marked_circle"));
                    cur_x = lx(i); // next segment starts AT the star's left
                }
            }
            '>' => {
                if i == start {
                    // ">" at start: converging lines (starting the segment)
                    result.push(Elem::Line(lx(i), ty(row)+H*0.25, cx(i), cy(row), "solid"));
                    result.push(Elem::Line(lx(i), ty(row)+H*0.75, cx(i), cy(row), "solid"));
                    cur_x = cx(i); // main line starts from center
                } else if i == end {
                    // ">" at end: right-pointing polygon
                    // First finish the current segment
                    if cur_x < lx(i) - 0.01 {
                        if is_double {
                            result.push(Elem::Line(cur_x, cy(row)-2.0, lx(i), cy(row)-2.0, "solid"));
                            result.push(Elem::Line(cur_x, cy(row)+2.0, lx(i), cy(row)+2.0, "solid"));
                        } else {
                            result.push(Elem::Line(cur_x, cy(row), lx(i), cy(row), line_class));
                        }
                    }
                    result.push(Elem::Polygon(vec![
                        (lx(i), ty(row)+H*0.25),
                        (rx(i), cy(row)),
                        (lx(i), ty(row)+H*0.75),
                    ], "filled"));
                    cur_x = rx(i); // past the arrow
                } else {
                    // ">" in middle: right-pointing polygon
                    if cur_x < lx(i) - 0.01 {
                        result.push(Elem::Line(cur_x, cy(row), lx(i), cy(row), line_class));
                    }
                    result.push(Elem::Polygon(vec![
                        (lx(i), ty(row)+H*0.25),
                        (rx(i), cy(row)),
                        (lx(i), ty(row)+H*0.75),
                    ], "filled"));
                    cur_x = rx(i);
                }
            }
            '<' => {
                if i == start {
                    // "<" at start: left-pointing polygon (arrow pointing left)
                    result.push(Elem::Polygon(vec![
                        (rx(i), ty(row)+H*0.25),
                        (lx(i), cy(row)),
                        (rx(i), ty(row)+H*0.75),
                    ], "filled"));
                    cur_x = rx(i);
                } else if i == end {
                    // "<" at end: right-facing V-shape (converging lines)
                    if cur_x < cx(i) - 0.01 {
                        result.push(Elem::Line(cur_x, cy(row), cx(i), cy(row), line_class));
                    }
                    result.push(Elem::Line(cx(i), cy(row), rx(i), ty(row)+H*0.25, "solid"));
                    result.push(Elem::Line(cx(i), cy(row), rx(i), ty(row)+H*0.75, "solid"));
                    cur_x = rx(i);
                } else {
                    // "<" in middle: left-pointing polygon
                    result.push(Elem::Polygon(vec![
                        (rx(i), ty(row)+H*0.25),
                        (lx(i), cy(row)),
                        (rx(i), ty(row)+H*0.75),
                    ], "filled"));
                    cur_x = rx(i);
                }
            }
            _ => {} // dash, corner, junction - just part of the line
        }
        i += 1;
    }

    // Add the final line segment
    if cur_x < x_end - 0.01 {
        if is_double {
            result.push(Elem::Line(cur_x, cy(row)-2.0, x_end, cy(row)-2.0, "solid"));
            result.push(Elem::Line(cur_x, cy(row)+2.0, x_end, cy(row)+2.0, "solid"));
        } else {
            // Check if we haven't already added the final segment
            let last_is_line = result.last().map_or(false, |e| matches!(e, Elem::Line(_,_,_,_,_)));
            result.push(Elem::Line(cur_x, cy(row), x_end, cy(row), line_class));
        }
    } else if (cur_x - x_end).abs() < 0.01 && cur_x == x_start {
        // Single special char segment with no actual line - add if needed
    }

    result
}

fn seg_start_x(grid: &Grid, start: i32, row: i32) -> f64 {
    let c = grid.get(start, row);
    match c {
        '-' | '~' => lx(start),
        '=' => lx(start),
        '+' => cx(start),
        '.' | '\'' | '`' | ',' => {
            let below = grid.get(start, row+1);
            let above = grid.get(start, row-1);
            if v_connects(below) || v_connects(above) { rx(start) } else { rx(start) }
        }
        'o' | 'O' => rx(start+1), // circle at start: line starts after first dash
        '*' => rx(start), // star at start: handled specially
        '>' => cx(start),
        '<' => rx(start),
        _ => lx(start),
    }
}

fn seg_end_x(grid: &Grid, _start: i32, end: i32, row: i32) -> f64 {
    let c = grid.get(end, row);
    match c {
        '-' | '~' => rx(end),
        '=' => rx(end),
        '+' => cx(end),
        '.' | '\'' | '`' | ',' => {
            let below = grid.get(end, row+1);
            let above = grid.get(end, row-1);
            if v_connects(below) || v_connects(above) { lx(end) } else { lx(end) }
        }
        'o' | 'O' => cx(end),
        '*' => cx(end),
        '>' => lx(end), // arrow at end, line stops before it
        '<' => cx(end),
        _ => rx(end),
    }
}

fn is_rect_h_side(start: i32, end: i32, row: i32, rects: &[(i32,i32,i32,i32,f64)]) -> bool {
    for &(c1,r1,c2,r2,_) in rects {
        // Check if this is the top or bottom side of a rect
        if (row == r1 || row == r2) && start == c1 && end == c2 {
            return true;
        }
    }
    false
}

fn find_rects(grid: &Grid) -> Vec<(i32,i32,i32,i32,f64)> {
    let mut rects = Vec::new();
    for r1 in 0..grid.num_rows as i32 {
        for c1 in 0..grid.num_cols as i32 {
            let tl = grid.get(c1, r1);
            if !is_tl_corner(tl) { continue; }
            for r2 in (r1+1)..grid.num_rows as i32 {
                for c2 in (c1+1)..grid.num_cols as i32 {
                    if !is_tr_corner(grid.get(c2, r1)) { continue; }
                    if !is_bl_corner(grid.get(c1, r2)) { continue; }
                    if !is_br_corner(grid.get(c2, r2)) { continue; }
                    let rx_val = corner_rx(tl);
                    if corner_rx(grid.get(c2,r1)) != rx_val { continue; }
                    if corner_rx(grid.get(c1,r2)) != rx_val { continue; }
                    if corner_rx(grid.get(c2,r2)) != rx_val { continue; }
                    // Check sides
                    let top_ok = (c1+1..c2).all(|c| is_h_side(grid.get(c, r1)));
                    let bot_ok = (c1+1..c2).all(|c| is_h_side(grid.get(c, r2)));
                    let lft_ok = (r1+1..r2).all(|r| grid.get(c1, r) == '|');
                    let rgt_ok = (r1+1..r2).all(|r| grid.get(c2, r) == '|');
                    if top_ok && bot_ok && lft_ok && rgt_ok {
                        rects.push((c1, r1, c2, r2, rx_val));
                    }
                }
            }
        }
    }
    rects
}

fn is_tl_corner(c: char) -> bool { matches!(c, '+'|'.'|',') }
fn is_tr_corner(c: char) -> bool { matches!(c, '+'|'.'|'`') }
fn is_bl_corner(c: char) -> bool { matches!(c, '+'|'\''|'`') }  
fn is_br_corner(c: char) -> bool { matches!(c, '+'|'\''|',') }
fn is_h_side(c: char) -> bool { matches!(c, '-'|'=') }
fn corner_rx(c: char) -> f64 { if c == '+' { 0.0 } else { 4.0 } }

fn add_rects(grid: &Grid, elems: Vec<Elem>, rects: &[(i32,i32,i32,i32,f64)]) -> Vec<Elem> {
    if rects.is_empty() { return elems; }

    // Collect which cells are part of rectangle borders
    let mut border_cells: std::collections::HashSet<(i32,i32)> = std::collections::HashSet::new();
    for &(c1,r1,c2,r2,_) in rects {
        for c in c1..=c2 { border_cells.insert((c,r1)); border_cells.insert((c,r2)); }
        for r in r1..=r2 { border_cells.insert((c1,r)); border_cells.insert((c2,r)); }
    }

    let mut result: Vec<Elem> = Vec::new();

    // Add rect elements
    for &(c1,r1,c2,r2,rx_val) in rects {
        result.push(Elem::Rect(
            cx(c1), cy(r1),
            (c2-c1) as f64 * W,
            (r2-r1) as f64 * H,
            rx_val,
            "solid nofill",
        ));
    }

    // Add non-rect elements, filtering out rect boundaries
    for elem in elems {
        if !is_rect_boundary(&elem, rects) {
            result.push(elem);
        }
    }

    result
}

fn is_rect_boundary(elem: &Elem, rects: &[(i32,i32,i32,i32,f64)]) -> bool {
    let eps = 0.1;
    match elem {
        Elem::Line(x1,y1,x2,y2,_) => {
            for &(c1,r1,c2,r2,_) in rects {
                let lx1 = cx(c1); let rx2 = cx(c2);
                let ty1 = cy(r1); let by2 = cy(r2);
                // Top horizontal
                if (y1-ty1).abs()<eps && (y2-ty1).abs()<eps && 
                   *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                // Bottom horizontal
                if (y1-by2).abs()<eps && (y2-by2).abs()<eps && 
                   *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                // Left vertical
                if (x1-lx1).abs()<eps && (x2-lx1).abs()<eps && 
                   *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
                // Right vertical
                if (x1-rx2).abs()<eps && (x2-rx2).abs()<eps && 
                   *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
            }
            false
        }
        Elem::Path(d,_) => {
            // Check if this is a corner arc for a rect
            for &(c1,r1,c2,r2,rx_val) in rects {
                if rx_val > 0.0 {
                    // Any corner arc touching rect corners
                    let corners_x = vec![fmt(cx(c1)), fmt(cx(c2))];
                    let corners_y = vec![fmt(cy(r1)), fmt(cy(r2))];
                    let corners_near = vec![
                        fmt(rx(c1)), fmt(lx(c2)),
                        fmt(cy(r1)-4.0), fmt(ty(r1)+H-4.0),
                        fmt(cy(r2)-4.0), fmt(ty(r2)+H-4.0),
                    ];
                    // Check if path references any of these coordinates
                    for cx_s in &corners_x {
                        if d.contains(cx_s.as_str()) {
                            for cy_s in &corners_y {
                                if d.contains(cy_s.as_str()) { return true; }
                            }
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn merge_vert(elems: Vec<Elem>) -> Vec<Elem> {
    let n = elems.len();
    let mut merged = vec![false; n];
    let mut result = Vec::new();
    let eps = 0.001;

    for i in 0..n {
        if merged[i] { continue; }
        if let Elem::Line(xi1, yi1, xi2, yi2, ci) = &elems[i] {
            if (xi1 - xi2).abs() < eps { // vertical
                let x = *xi1;
                let class = *ci;
                let mut ys = (*yi1).min(*yi2);
                let mut ye = (*yi1).max(*yi2);

                let mut changed = true;
                while changed {
                    changed = false;
                    for j in (i+1)..n {
                        if merged[j] { continue; }
                        if let Elem::Line(xj1, yj1, xj2, yj2, cj) = &elems[j] {
                            if (xj1 - x).abs() < eps && (xj2 - x).abs() < eps && *cj == class {
                                let js = (*yj1).min(*yj2);
                                let je = (*yj1).max(*yj2);
                                if js <= ye + eps && je >= ys - eps {
                                    ys = ys.min(js);
                                    ye = ye.max(je);
                                    merged[j] = true;
                                    changed = true;
                                }
                            }
                        }
                    }
                }
                merged[i] = true;
                result.push(Elem::Line(x, ys, x, ye, class));
                continue;
            }
        }
        result.push(elems[i].clone());
    }
    result
}

fn group_elements(elems: Vec<Elem>) -> Vec<Vec<Elem>> {
    let mut groups: Vec<Vec<Elem>> = Vec::new();

    'outer: for elem in elems {
        match &elem {
            Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..) => {
                groups.push(vec![elem]);
                continue;
            }
            _ => {}
        }

        for g in &mut groups {
            let conn = g.iter().any(|ge| {
                !matches!(ge, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..))
                    && ge.shares_pt(&elem)
            });
            if conn {
                g.push(elem);
                continue 'outer;
            }
        }
        groups.push(vec![elem]);
    }

    // Merge connected groups
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let conn = groups[i].iter().any(|a| {
                    if matches!(a, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..)) { return false; }
                    groups[j].iter().any(|b| {
                        if matches!(b, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..)) { return false; }
                        a.shares_pt(b)
                    })
                });
                if conn {
                    let g = groups.remove(j);
                    groups[i].extend(g);
                    changed = true;
                } else {
                    j += 1;
                }
            }
            i += 1;
        }
    }

    groups
}

fn render_elem(e: &Elem, scale: f64) -> String {
    match e {
        Elem::Line(x1,y1,x2,y2,c) => format!(
            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
            fmt(x1*scale), fmt(y1*scale), fmt(x2*scale), fmt(y2*scale), c
        ),
        Elem::Path(d, c) => format!(
            "  <path d=\"{}\" class=\"{}\"></path>\n",
            scale_path(d, scale), c
        ),
        Elem::Circle(cx,cy,r,c) => format!(
            "  <circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}\"></circle>\n",
            fmt(cx*scale), fmt(cy*scale), fmt(r*scale), c
        ),
        Elem::Polygon(pts, c) => {
            let ps: Vec<String> = pts.iter().map(|(x,y)| format!("{},{}", fmt(x*scale), fmt(y*scale))).collect();
            format!("  <polygon points=\"{}\" class=\"{}\"></polygon>\n", ps.join(" "), c)
        }
        Elem::Text(x,y,s) => format!(
            "  <text x=\"{}\" y=\"{}\" >{}</text>\n",
            fmt(x*scale), fmt(y*scale), s
        ),
        Elem::Rect(x,y,w,h,rx,c) => format!(
            "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>\n",
            fmt(x*scale), fmt(y*scale), fmt(w*scale), fmt(h*scale), c, fmt(rx*scale)
        ),
    }
}

fn scale_path(d: &str, scale: f64) -> String {
    if (scale - 1.0).abs() < 0.001 { return d.to_string(); }
    let parts: Vec<&str> = d.split_whitespace().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "M" => {
                out.push("M".to_string());
                i += 1;
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; }
            }
            "A" => {
                out.push("A".to_string());
                i += 1;
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; } // rx,ry
                if i < parts.len() { out.push(parts[i].to_string()); i += 1; } // rotation,laf,sf
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; } // x,y
            }
            _ => { out.push(parts[i].to_string()); i += 1; }
        }
    }
    out.join(" ")
}

fn scale_xy(s: &str, scale: f64) -> String {
    if let Some((a, b)) = s.split_once(',') {
        let x: f64 = a.parse().unwrap_or(0.0);
        let y: f64 = b.parse().unwrap_or(0.0);
        format!("{},{}", fmt(x*scale), fmt(y*scale))
    } else { s.to_string() }
}

fn html_escape_str(c: char) -> String {
    match c { '<' => "&lt;".to_string(), '>' => "&gt;".to_string(),
              '&' => "&amp;".to_string(), '\'' => "&#39;".to_string(),
              '"' => "&quot;".to_string(), _ => c.to_string() }
}

fn html_escape_ch(c: char) -> String { html_escape_str(c) }

fn generate_style(s: &Settings) -> String {
    format!(
"  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{
  stroke: {stroke};
  stroke-width: {sw};
  stroke-opacity: 1;
  fill-opacity: 1;
  stroke-linecap: round;
  stroke-linejoin: miter;
}}

.svgbob text {{
  white-space: pre;
  fill: {stroke};
  font-family: {ff};
  font-size: {fs}px;
}}

.svgbob rect.backdrop {{
  stroke: none;
  fill: {bg};
}}

.svgbob .broken {{
  stroke-dasharray: 8;
}}

.svgbob .filled {{
  fill: {fill};
}}

