            let c = grid.get(col, row);

            if c == ' ' { col += 1; continue; }

            if is_drawing(c) {
                // Check if this is the start of a horizontal segment
                if h_line(c) || (h_connects(c) && {
                    let right = grid.get(col+1, row);
                    h_connects(right) || h_line(right)
                }) {
                    // Find the extent of this horizontal segment
                    let seg_start = col;
                    let mut seg_end = col;

                    // Find end of segment: chars that continue horizontal connection
                    let mut j = col;
                    while j <= grid.num_cols as i32 {
                        let ch = grid.get(j, row);
                        if h_line(ch) {
                            seg_end = j;
                            j += 1;
                        } else if h_connects(ch) {
                            // Check if this connector has horizontal connections on both sides
                            let left_ch = grid.get(j-1, row);
                            let right_ch = grid.get(j+1, row);
                            let left_ok = h_line(left_ch) || h_connects(left_ch);
                            let right_ok = h_line(right_ch) || h_connects(right_ch);
                            if j == seg_start { // at start: need right connection
                                if right_ok {
                                    seg_end = j;
                                    j += 1;
                                } else {
                                    break;
                                }
                            } else if left_ok && right_ok {
                                seg_end = j;
                                j += 1;
                            } else if left_ok && !right_ok {
                                seg_end = j;
                                j += 1;
                                break;
                            } else {
                                break;
                            }
                        } else {
