                        elems.push(Elem::Line(cx(col), ty(row), rx(col), by(row), "solid"));
                    } else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "^".to_string()));
                    }
                    col += 1;
                    continue;
                }

                // v arrow
                if c == 'v' {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = v_connects(above);
                    let has_below = v_connects(below);
                    if has_above {
                        elems.push(Elem::Polygon(vec![
                            (lx(col), ty(row)+H*0.25),
                            (rx(col), ty(row)+H*0.25),
