        if is_double {
            result.push(Elem::Line(cur_x, cy(row)-2.0, x_end, cy(row)-2.0, "solid"));
            result.push(Elem::Line(cur_x, cy(row)+2.0, x_end, cy(row)+2.0, "solid"));
        } else {
            // Check if we haven't already added the final segment
            let last_is_line = result.last().map_or(false, |e| matches!(e, Elem::Line(_,_,_,_,_)));
            result.push(Elem::Line(cur_x, cy(row), x_end, cy(row), line_class));
        }
    } else if (cur_x - x_end).abs() < 0.01 && cur_x == x_start {
        // Single special char segment with no actual line - add if needed
    }

    result
}

fn seg_start_x(grid: &Grid, start: i32, row: i32) -> f64 {
    let c = grid.get(start, row);
    match c {
        '-' | '~' => lx(start),
        '=' => lx(start),
        '+' => cx(start),
        '.' | '\'' | '`' | ',' => {
            let below = grid.get(start, row+1);
            let above = grid.get(start, row-1);
            if v_connects(below) || v_connects(above) { rx(start) } else { rx(start) }
        }
        'o' | 'O' => rx(start+1), // circle at start: line starts after first dash
        '*' => rx(start), // star at start: handled specially
        '>' => cx(start),
        '<' => rx(start),
        _ => lx(start),
    }
}

fn seg_end_x(grid: &Grid, _start: i32, end: i32, row: i32) -> f64 {
    let c = grid.get(end, row);
    match c {
        '-' | '~' => rx(end),
        '=' => rx(end),
        '+' => cx(end),
        '.' | '\'' | '`' | ',' => {
            let below = grid.get(end, row+1);
            let above = grid.get(end, row-1);
            if v_connects(below) || v_connects(above) { lx(end) } else { lx(end) }
        }
        'o' | 'O' => cx(end),
        '*' => cx(end),
        '>' => lx(end), // arrow at end, line stops before it
        '<' => cx(end),
        _ => rx(end),
    }
}

fn is_rect_h_side(start: i32, end: i32, row: i32, rects: &[(i32,i32,i32,i32,f64)]) -> bool {
    for &(c1,r1,c2,r2,_) in rects {
        // Check if this is the top or bottom side of a rect
        if (row == r1 || row == r2) && start == c1 && end == c2 {
            return true;
        }
    }
    false
}

fn find_rects(grid: &Grid) -> Vec<(i32,i32,i32,i32,f64)> {
    let mut rects = Vec::new();
    for r1 in 0..grid.num_rows as i32 {
        for c1 in 0..grid.num_cols as i32 {
            let tl = grid.get(c1, r1);
            if !is_tl_corner(tl) { continue; }
            for r2 in (r1+1)..grid.num_rows as i32 {
                for c2 in (c1+1)..grid.num_cols as i32 {
                    if !is_tr_corner(grid.get(c2, r1)) { continue; }
                    if !is_bl_corner(grid.get(c1, r2)) { continue; }
                    if !is_br_corner(grid.get(c2, r2)) { continue; }
                    let rx_val = corner_rx(tl);
                    if corner_rx(grid.get(c2,r1)) != rx_val { continue; }
                    if corner_rx(grid.get(c1,r2)) != rx_val { continue; }
                    if corner_rx(grid.get(c2,r2)) != rx_val { continue; }
                    // Check sides
                    let top_ok = (c1+1..c2).all(|c| is_h_side(grid.get(c, r1)));
                    let bot_ok = (c1+1..c2).all(|c| is_h_side(grid.get(c, r2)));
                    let lft_ok = (r1+1..r2).all(|r| grid.get(c1, r) == '|');
                    let rgt_ok = (r1+1..r2).all(|r| grid.get(c2, r) == '|');
                    if top_ok && bot_ok && lft_ok && rgt_ok {
                        rects.push((c1, r1, c2, r2, rx_val));
                    }
                }
            }
        }
    }
    rects
}

fn is_tl_corner(c: char) -> bool { matches!(c, '+'|'.'|',') }
fn is_tr_corner(c: char) -> bool { matches!(c, '+'|'.'|'`') }
fn is_bl_corner(c: char) -> bool { matches!(c, '+'|'\''|'`') }  
fn is_br_corner(c: char) -> bool { matches!(c, '+'|'\''|',') }
fn is_h_side(c: char) -> bool { matches!(c, '-'|'=') }
fn corner_rx(c: char) -> f64 { if c == '+' { 0.0 } else { 4.0 } }

fn add_rects(grid: &Grid, elems: Vec<Elem>, rects: &[(i32,i32,i32,i32,f64)]) -> Vec<Elem> {
    if rects.is_empty() { return elems; }

    // Collect which cells are part of rectangle borders
    let mut border_cells: std::collections::HashSet<(i32,i32)> = std::collections::HashSet::new();
    for &(c1,r1,c2,r2,_) in rects {
        for c in c1..=c2 { border_cells.insert((c,r1)); border_cells.insert((c,r2)); }
        for r in r1..=r2 { border_cells.insert((c1,r)); border_cells.insert((c2,r)); }
    }

    let mut result: Vec<Elem> = Vec::new();

    // Add rect elements
    for &(c1,r1,c2,r2,rx_val) in rects {
        result.push(Elem::Rect(
            cx(c1), cy(r1),
            (c2-c1) as f64 * W,
            (r2-r1) as f64 * H,
            rx_val,
            "solid nofill",
        ));
    }

    // Add non-rect elements, filtering out rect boundaries
    for elem in elems {
        if !is_rect_boundary(&elem, rects) {
            result.push(elem);
        }
    }

    result
}

fn is_rect_boundary(elem: &Elem, rects: &[(i32,i32,i32,i32,f64)]) -> bool {
    let eps = 0.1;
    match elem {
        Elem::Line(x1,y1,x2,y2,_) => {
            for &(c1,r1,c2,r2,_) in rects {
                let lx1 = cx(c1); let rx2 = cx(c2);
                let ty1 = cy(r1); let by2 = cy(r2);
                // Top horizontal
                if (y1-ty1).abs()<eps && (y2-ty1).abs()<eps && 
                   *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                // Bottom horizontal
                if (y1-by2).abs()<eps && (y2-by2).abs()<eps && 
                   *x1 >= lx1-eps && *x2 <= rx2+eps { return true; }
                // Left vertical
                if (x1-lx1).abs()<eps && (x2-lx1).abs()<eps && 
                   *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
                // Right vertical
                if (x1-rx2).abs()<eps && (x2-rx2).abs()<eps && 
                   *y1 >= ty1-eps && *y2 <= by2+eps { return true; }
            }
            false
        }
        Elem::Path(d,_) => {
            // Check if this is a corner arc for a rect
            for &(c1,r1,c2,r2,rx_val) in rects {
                if rx_val > 0.0 {
                    // Any corner arc touching rect corners
                    let corners_x = vec![fmt(cx(c1)), fmt(cx(c2))];
                    let corners_y = vec![fmt(cy(r1)), fmt(cy(r2))];
                    let corners_near = vec![
                        fmt(rx(c1)), fmt(lx(c2)),
                        fmt(cy(r1)-4.0), fmt(ty(r1)+H-4.0),
                        fmt(cy(r2)-4.0), fmt(ty(r2)+H-4.0),
                    ];
                    // Check if path references any of these coordinates
                    for cx_s in &corners_x {
                        if d.contains(cx_s.as_str()) {
                            for cy_s in &corners_y {
                                if d.contains(cy_s.as_str()) { return true; }
                            }
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn merge_vert(elems: Vec<Elem>) -> Vec<Elem> {
    let n = elems.len();
    let mut merged = vec![false; n];
    let mut result = Vec::new();
    let eps = 0.001;

    for i in 0..n {
        if merged[i] { continue; }
        if let Elem::Line(xi1, yi1, xi2, yi2, ci) = &elems[i] {
            if (xi1 - xi2).abs() < eps { // vertical
                let x = *xi1;
                let class = *ci;
                let mut ys = (*yi1).min(*yi2);
                let mut ye = (*yi1).max(*yi2);

                let mut changed = true;
                while changed {
                    changed = false;
                    for j in (i+1)..n {
                        if merged[j] { continue; }
                        if let Elem::Line(xj1, yj1, xj2, yj2, cj) = &elems[j] {
                            if (xj1 - x).abs() < eps && (xj2 - x).abs() < eps && *cj == class {
                                let js = (*yj1).min(*yj2);
                                let je = (*yj1).max(*yj2);
                                if js <= ye + eps && je >= ys - eps {
                                    ys = ys.min(js);
                                    ye = ye.max(je);
                                    merged[j] = true;
                                    changed = true;
                                }
                            }
                        }
                    }
                }
                merged[i] = true;
                result.push(Elem::Line(x, ys, x, ye, class));
                continue;
            }
        }
        result.push(elems[i].clone());
    }
    result
}

fn group_elements(elems: Vec<Elem>) -> Vec<Vec<Elem>> {
    let mut groups: Vec<Vec<Elem>> = Vec::new();

    'outer: for elem in elems {
        match &elem {
            Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..) => {
                groups.push(vec![elem]);
                continue;
            }
            _ => {}
        }

        for g in &mut groups {
            let conn = g.iter().any(|ge| {
                !matches!(ge, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..))
                    && ge.shares_pt(&elem)
            });
            if conn {
                g.push(elem);
                continue 'outer;
            }
        }
        groups.push(vec![elem]);
    }

    // Merge connected groups
    let mut changed = true;
    while changed {
        changed = false;
        let mut i = 0;
        while i < groups.len() {
            let mut j = i + 1;
            while j < groups.len() {
                let conn = groups[i].iter().any(|a| {
                    if matches!(a, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..)) { return false; }
                    groups[j].iter().any(|b| {
                        if matches!(b, Elem::Text(..) | Elem::Rect(..) | Elem::Circle(..)) { return false; }
                        a.shares_pt(b)
                    })
                });
                if conn {
                    let g = groups.remove(j);
                    groups[i].extend(g);
                    changed = true;
                } else {
                    j += 1;
                }
            }
            i += 1;
        }
    }

    groups
}

fn render_elem(e: &Elem, scale: f64) -> String {
    match e {
        Elem::Line(x1,y1,x2,y2,c) => format!(
            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
            fmt(x1*scale), fmt(y1*scale), fmt(x2*scale), fmt(y2*scale), c
        ),
        Elem::Path(d, c) => format!(
            "  <path d=\"{}\" class=\"{}\"></path>\n",
            scale_path(d, scale), c
        ),
        Elem::Circle(cx,cy,r,c) => format!(
            "  <circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}\"></circle>\n",
            fmt(cx*scale), fmt(cy*scale), fmt(r*scale), c
        ),
        Elem::Polygon(pts, c) => {
            let ps: Vec<String> = pts.iter().map(|(x,y)| format!("{},{}", fmt(x*scale), fmt(y*scale))).collect();
            format!("  <polygon points=\"{}\" class=\"{}\"></polygon>\n", ps.join(" "), c)
        }
        Elem::Text(x,y,s) => format!(
            "  <text x=\"{}\" y=\"{}\" >{}</text>\n",
            fmt(x*scale), fmt(y*scale), s
        ),
        Elem::Rect(x,y,w,h,rx,c) => format!(
            "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>\n",
            fmt(x*scale), fmt(y*scale), fmt(w*scale), fmt(h*scale), c, fmt(rx*scale)
        ),
    }
}

fn scale_path(d: &str, scale: f64) -> String {
    if (scale - 1.0).abs() < 0.001 { return d.to_string(); }
    let parts: Vec<&str> = d.split_whitespace().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < parts.len() {
        match parts[i] {
            "M" => {
                out.push("M".to_string());
                i += 1;
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; }
            }
            "A" => {
                out.push("A".to_string());
                i += 1;
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; } // rx,ry
                if i < parts.len() { out.push(parts[i].to_string()); i += 1; } // rotation,laf,sf
                if i < parts.len() { out.push(scale_xy(parts[i], scale)); i += 1; } // x,y
            }
            _ => { out.push(parts[i].to_string()); i += 1; }
        }
    }
    out.join(" ")
}

fn scale_xy(s: &str, scale: f64) -> String {
    if let Some((a, b)) = s.split_once(',') {
        let x: f64 = a.parse().unwrap_or(0.0);
        let y: f64 = b.parse().unwrap_or(0.0);
        format!("{},{}", fmt(x*scale), fmt(y*scale))
    } else { s.to_string() }
}

fn html_escape_str(c: char) -> String {
    match c { '<' => "&lt;".to_string(), '>' => "&gt;".to_string(),
              '&' => "&amp;".to_string(), '\'' => "&#39;".to_string(),
              '"' => "&quot;".to_string(), _ => c.to_string() }
}

fn html_escape_ch(c: char) -> String { html_escape_str(c) }

