                let s = render_elem(elem, scale);
                for line in s.lines() {
                    svg.push_str("  ");
                    svg.push_str(line);
                    svg.push('\n');
                }
            }
            svg.push_str("  </g>\n");
        }
    }

    svg.push_str("</svg>\n");
    svg
}

fn fmt(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e10 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

// Grid: represents the text as a 2D array of chars
struct Grid {
    rows: Vec<Vec<char>>,
    num_rows: usize,
    num_cols: usize,
}

impl Grid {
    fn new(text: &str) -> Self {
        let raw_lines: Vec<&str> = text.split('\n').collect();
        let mut end = raw_lines.len();
        while end > 0 && raw_lines[end-1].chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            end -= 1;
        }
        let lines = &raw_lines[..end];
        let rows: Vec<Vec<char>> = lines.iter().map(|line| {
            let s = line.trim_end_matches(|c: char| c == ' ' || c == '\r');
            s.chars().collect()
        }).collect();
        let num_rows = rows.len();
        let num_cols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
        Grid { rows, num_rows, num_cols }
    }

    fn get(&self, col: i32, row: i32) -> char {
        if row < 0 || col < 0 { return ' '; }
        let r = row as usize; let c = col as usize;
        if r >= self.num_rows { return ' '; }
        if c >= self.rows[r].len() { return ' '; }
        self.rows[r][c]
    }
}

// Coordinate helpers
fn lx(c: i32) -> f64 { c as f64 * W }
fn rx(c: i32) -> f64 { (c+1) as f64 * W }
fn cx(c: i32) -> f64 { c as f64 * W + W/2.0 }
fn ty(r: i32) -> f64 { r as f64 * H }
fn by(r: i32) -> f64 { (r+1) as f64 * H }
fn cy(r: i32) -> f64 { r as f64 * H + H/2.0 }

// SVG elements
#[derive(Debug, Clone)]
enum Elem {
    Line(f64, f64, f64, f64, &'static str),
    Path(String, &'static str),
    Circle(f64, f64, f64, &'static str),
    Polygon(Vec<(f64,f64)>, &'static str),
    Text(f64, f64, String),
    Rect(f64, f64, f64, f64, f64, &'static str), // x,y,w,h,rx,class
}

impl Elem {
    fn endpoints(&self) -> Vec<(f64,f64)> {
        match self {
            Elem::Line(x1,y1,x2,y2,_) => vec![(*x1,*y1),(*x2,*y2)],
            Elem::Polygon(pts,_) => pts.iter().take(1).chain(pts.iter().last()).map(|&p|p).collect(),
            _ => vec![],
        }
    }

    fn shares_pt(&self, other: &Elem) -> bool {
        let eps = |a:f64,b:f64| (a-b).abs() < 0.1;
        let eq = |(ax,ay):(f64,f64),(bx,by):(f64,f64)| eps(ax,bx) && eps(ay,by);
        for p in self.endpoints() {
            for q in other.endpoints() {
                if eq(p,q) { return true; }
            }
        }
        false
    }
}

fn is_drawing(c: char) -> bool {
    matches!(c, '-'|'='|'~'|'|'|':'|'/'|'\\'|'_'|'+'|'.'|'\''|'`'|','|'*'|'o'|'O'|'>'|'<'|'^'|'v'|'('|')')
}

fn h_line(c: char) -> bool { matches!(c, '-'|'='|'~') }
fn v_connects(c: char) -> bool {
    matches!(c, '|'|':'|'+'|'.'|'\''|'`'|','|'^'|'v'|'o'|'O'|'*')
}
fn h_connects(c: char) -> bool {
    matches!(c, '-'|'='|'~'|'+'|'.'|'\''|'`'|','|'o'|'O'|'*'|'>'|'<')
}
fn is_corner(c: char) -> bool { matches!(c, '.'|'\''|'`'|',') }

fn render_grid(grid: &Grid) -> Vec<Elem> {
    let mut elems: Vec<Elem> = Vec::new();

    // Detect complete rectangles first
    let rects = find_rects(grid);

    // Process each row for horizontal elements
    for row in 0..grid.num_rows as i32 {
        let mut col = 0i32;
        while col <= grid.num_cols as i32 {
            let c = grid.get(col, row);

            if c == ' ' { col += 1; continue; }

            if is_drawing(c) {
                // Check if this is the start of a horizontal segment
                if h_line(c) || (h_connects(c) && {
                    let right = grid.get(col+1, row);
                    h_connects(right) || h_line(right)
                }) {
                    // Find the extent of this horizontal segment
                    let seg_start = col;
                    let mut seg_end = col;

                    // Find end of segment: chars that continue horizontal connection
                    let mut j = col;
                    while j <= grid.num_cols as i32 {
                        let ch = grid.get(j, row);
                        if h_line(ch) {
                            seg_end = j;
                            j += 1;
                        } else if h_connects(ch) {
                            // Check if this connector has horizontal connections on both sides
                            let left_ch = grid.get(j-1, row);
                            let right_ch = grid.get(j+1, row);
                            let left_ok = h_line(left_ch) || h_connects(left_ch);
                            let right_ok = h_line(right_ch) || h_connects(right_ch);
                            if j == seg_start { // at start: need right connection
                                if right_ok {
                                    seg_end = j;
                                    j += 1;
                                } else {
                                    break;
                                }
                            } else if left_ok && right_ok {
                                seg_end = j;
                                j += 1;
                            } else if left_ok && !right_ok {
                                seg_end = j;
                                j += 1;
                                break;
                            } else {
                                break;
                            }
                        } else {
                            break;
                        }
                    }

                    if seg_end >= seg_start {
                        let mut seg_elems = gen_h_segment(grid, seg_start, seg_end, row, &rects);
                        elems.append(&mut seg_elems);
                        col = seg_end + 1;
                        continue;
                    }
                }

                // Vertical line
                if c == '|' || c == ':' {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = v_connects(above) || above == '|' || above == ':';
                    let has_below = v_connects(below) || below == '|' || below == ':';
                    if c == ':' && !has_above && !has_below {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, ":".to_string()));
                    } else {
                        let class = if c == ':' { "broken" } else { "solid" };
                        elems.push(Elem::Line(cx(col), ty(row), cx(col), by(row), class));
                    }
                    col += 1;
                    continue;
                }

                // Diagonal /
                if c == '/' {
                    elems.push(Elem::Line(rx(col), ty(row), lx(col), by(row), "solid"));
                    col += 1;
                    continue;
                }

                // Diagonal \
                if c == '\\' {
                    elems.push(Elem::Line(lx(col), ty(row), rx(col), by(row), "solid"));
                    col += 1;
                    continue;
                }

                // Underscore
                if c == '_' {
                    let start = col;
                    while col <= grid.num_cols as i32 && grid.get(col, row) == '_' {
                        col += 1;
                    }
                    elems.push(Elem::Line(lx(start), by(row), lx(col), by(row), "solid"));
                    continue;
                }

                // ^ arrow
                if c == '^' {
                    let below = grid.get(col, row+1);
                    let above = grid.get(col, row-1);
                    let has_below = v_connects(below);
                    let has_above = v_connects(above);
                    if has_below {
                        elems.push(Elem::Polygon(vec![
                            (lx(col), ty(row)+H*0.75),
                            (cx(col), ty(row)),
                            (rx(col), ty(row)+H*0.75),
                        ], "filled"));
                    } else if has_above {
                        elems.push(Elem::Line(cx(col), ty(row), lx(col), by(row), "solid"));
                        elems.push(Elem::Line(cx(col), ty(row), rx(col), by(row), "solid"));
                    } else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "^".to_string()));
                    }
                    col += 1;
                    continue;
                }

                // v arrow
                if c == 'v' {
                    let above = grid.get(col, row-1);
                    let below = grid.get(col, row+1);
                    let has_above = v_connects(above);
                    let has_below = v_connects(below);
                    if has_above {
                        elems.push(Elem::Polygon(vec![
                            (lx(col), ty(row)+H*0.25),
                            (rx(col), ty(row)+H*0.25),
                            (cx(col), by(row)),
                        ], "filled"));
                    } else if has_below {
                        elems.push(Elem::Line(lx(col), ty(row), cx(col), by(row), "solid"));
                        elems.push(Elem::Line(rx(col), ty(row), cx(col), by(row), "solid"));
                    } else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "v".to_string()));
                    }
                    col += 1;
                    continue;
                }

                // ( arc or circle
                if c == '(' {
                    let next = grid.get(col+1, row);
                    if next == ')' {
                        elems.push(Elem::Circle(rx(col), cy(row), W/2.0, "nofill"));
                        col += 2;
                        continue;
                    } else {
                        let d = format!("M {},{} A 16,16 0,0,0 {},{}",
                            fmt(rx(col)), fmt(ty(row)), fmt(rx(col)), fmt(by(row)));
                        elems.push(Elem::Path(d, "nofill"));
                        col += 1;
                        continue;
                    }
                }

                // ) arc
                if c == ')' {
                    let d = format!("M {},{} A 16,16 0,0,1 {},{}",
                        fmt(lx(col)), fmt(ty(row)), fmt(lx(col)), fmt(by(row)));
                    elems.push(Elem::Path(d, "nofill"));
                    col += 1;
                    continue;
                }

                // Other drawing chars that aren't part of a horizontal segment:
                // +, ., ', `, ,, *, o, O  -> only rendered when they're part of a segment
                // If we get here, they're isolated drawing chars -> render as text or skip
                if matches!(c, '+'|'.'|'\''|'`'|','|'*'|'o'|'O') {
                    // These are only drawing in context - as standalone they're text (or skip for +)
                    if c != '+' {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, html_escape_str(c)));
                    }
                    col += 1;
                    continue;
                }

                // > and < - isolated arrows
                if c == '>' {
                    let left = grid.get(col-1, row);
                    let right = grid.get(col+1, row);
                    if h_connects(left) { /* will be handled by horizontal segment */ }
                    else {
                        elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "&gt;".to_string()));
                    }
                    col += 1;
                    continue;
                }
                if c == '<' {
                    elems.push(Elem::Text(lx(col)+2.0, cy(row)+4.0, "&lt;".to_string()));
                    col += 1;
                    continue;
                }
            }

            // Text character - scan a run
            if !is_drawing(c) && c != ' ' {
                let start_col = col;
                let mut text = String::new();
                while col <= grid.num_cols as i32 {
                    let ch = grid.get(col, row);
                    if ch == ' ' || is_drawing(ch) { break; }
                    text.push_str(&html_escape_ch(ch));
                    col += 1;
                }
                if !text.is_empty() {
                    elems.push(Elem::Text(lx(start_col)+2.0, cy(row)+4.0, text));
                }
                continue;
            }

            col += 1;
        }
    }

    // Merge vertical lines
    let elems = merge_vert(elems);

    // Add rect elements for detected rectangles (replacing the individual lines)
    add_rects(grid, elems, &rects)
}

fn gen_h_segment(grid: &Grid, start: i32, end: i32, row: i32, rects: &[(i32,i32,i32,i32,f64)]) -> Vec<Elem> {
    let mut result = Vec::new();

    // Check if this segment is part of a rectangle boundary
    if is_rect_h_side(start, end, row, rects) {
        return result; // Skip - handled by rect element
    }

    let sc = grid.get(start, row);
    let ec = grid.get(end, row);

    // Determine line type
    let is_broken = (start..=end).any(|c| grid.get(c, row) == '~');
    let is_double = !is_broken && (start..=end).all(|c| {
        let ch = grid.get(c, row);
        ch == '=' || is_corner(ch) || ch == '+'
    }) && (start..=end).any(|c| grid.get(c, row) == '=');

    let line_class: &'static str = if is_broken { "broken" } else { "solid" };

    // Generate corner arcs if needed
    if is_corner(sc) {
        let below = grid.get(start, row+1);
        let above = grid.get(start, row-1);
        let vb = v_connects(below);
        let va = v_connects(above);
        if vb && !va {
            // Top-left corner arc
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(rx(start)), fmt(cy(row)),
                fmt(cx(start)), fmt(ty(row+1)-4.0));
            result.push(Elem::Path(d, "nofill"));
        } else if va && !vb {
            // Bottom-left corner arc
            let d = format!("M {},{} A 4,4 0,0,0 {},{}",
                fmt(cx(start)), fmt(cy(row)-4.0),
                fmt(rx(start)), fmt(cy(row)));
            result.push(Elem::Path(d, "nofill"));
        }
    }

    if is_corner(ec) && start != end {
        let below = grid.get(end, row+1);
        let above = grid.get(end, row-1);
        let vb = v_connects(below);
        let va = v_connects(above);
        if vb && !va {
            // Top-right corner arc
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(lx(end)), fmt(cy(row)),
                fmt(cx(end)), fmt(ty(row+1)-4.0));
            result.push(Elem::Path(d, "nofill"));
        } else if va && !vb {
            // Bottom-right corner arc
            let d = format!("M {},{} A 4,4 0,0,1 {},{}",
                fmt(cx(end)), fmt(cy(row)-4.0),
                fmt(lx(end)), fmt(cy(row)));
            result.push(Elem::Path(d, "nofill"));
        }
    }

