                    cur_x = rx(i);
                } else {
                    // In middle or at end
                    result.push(Elem::Line(cur_x, cy(row), cx(i), cy(row), "solid end_marked_circle"));
                    cur_x = lx(i); // next segment starts AT the star's left
                }
            }
            '>' => {
                if i == start {
