            Elem::Circle(_,cy,r,_) => *cy - *r,
            Elem::Text(_,y,_) => *y,
            Elem::Rect(_,y,_,_,_,_) => *y,
            Elem::Path(d,_) => {
                if let Some(s) = d.strip_prefix("M ") {
                    if let Some(comma) = s.find(',') {
