        let (eff_y, eff_x) = if g.len() > 1 {
            // Multi-element group: use max_y, x=0
            let max_y = g.iter().map(|e| elem_max_y_f(e)).fold(f64::NEG_INFINITY, f64::max);
            (max_y, 0.0)
