                    // Rect: use min_y, min_x
                    let min_x = elem_min_x_f(&g[0]);
                    (*y, min_x)
                }
                _ => {
                    // Standalone: use max_y, min_x
                    let max_y = elem_max_y_f(&g[0]);
                    let min_x = elem_min_x_f(&g[0]);
                    (max_y, min_x)
                }
            }
        };
        let row = (eff_y / h_unit) as i64;
        let _ = eff_x; // not used in sort key
        (row, idx, g)
    }).collect();
    sorted_groups.sort_by_key(|(row, idx, _)| (*row, *idx));\n    let sorted_groups: Vec<Vec<Elem>> = sorted_groups.into_iter().map(|(_,_,g)| g).collect();"""

new_sort_key = """    // sort_type: 0=polygon/path, 1=group, 2=other
    let mut sorted_groups: Vec<(i64, i32, usize, Vec<Elem>)> = groups.into_iter().enumerate().map(|(idx, g)| {
        let (eff_y, sort_type) = if g.len() > 1 {
            // Multi-element group: use max_y
            let max_y = g.iter().map(|e| elem_max_y_f(e)).fold(f64::NEG_INFINITY, f64::max);
            (max_y, 1i32) // sort_type=1 (group, comes AFTER standalone polygon)
        } else {
            match &g[0] {
                Elem::Rect(_,y,_,_,_,_) => {
                    (*y, 2i32) // Rect: use min_y, sort_type=2
