        (row, sort_type, idx, g)
    }).collect();
    sorted_groups.sort_by_key(|(row, stype, idx, _)| (*row, *stype, *idx));
    let sorted_groups: Vec<Vec<Elem>> = sorted_groups.into_iter().map(|(_,_,_,g)| g).collect();"""

