# Path endpoints returns vec![] (empty)!
# This means Paths never contribute to the shares_pt check.
# So Arc1 and Horiz1 DON'T share a point as far as my code is concerned.

# Fix: Paths need to return their endpoints (start and end of the arc).
# For arc paths like "M x1,y1 A ... x2,y2", I need to extract (x1,y1) and (x2,y2).

python3 << 'EOF'
with open('/workspace/src/render.rs', 'r') as f:
    content = f.read()

old_endpoints = """    fn endpoints(&self) -> Vec<(f64,f64)> {
        match self {
            Elem::Line(x1,y1,x2,y2,_) => vec![(*x1,*y1),(*x2,*y2)],
            Elem::Polygon(pts,_) => pts.iter().take(1).chain(pts.iter().last()).map(|&p|p).collect(),
            _ => vec![],
        }
    }"""

new_endpoints = """    fn endpoints(&self) -> Vec<(f64,f64)> {
        match self {
            Elem::Line(x1,y1,x2,y2,_) => vec![(*x1,*y1),(*x2,*y2)],
            Elem::Polygon(pts,_) => pts.iter().take(1).chain(pts.iter().last()).map(|&p|p).collect(),
            Elem::Path(d, _) => {
                // Extract start and end points from path "M x1,y1 A ... x2,y2"
                let mut pts = Vec::new();
                let parts: Vec<&str> = d.split_whitespace().collect();
                // Start point: after "M"
                if parts.len() > 1 && parts[0] == "M" {
                    if let Some((xs, ys)) = parts[1].split_once(',') {
                        if let (Ok(x), Ok(y)) = (xs.parse::<f64>(), ys.parse::<f64>()) {
                            pts.push((x, y));
                        }
                    }
                }
                // End point: last coordinate pair
                if let Some(last) = parts.last() {
                    if let Some((xs, ys)) = last.split_once(',') {
                        if let (Ok(x), Ok(y)) = (xs.parse::<f64>(), ys.parse::<f64>()) {
                            pts.push((x, y));
                        }
                    }
                }
                pts
            }
            _ => vec![],
        }
    }"""

content = content.replace(old_endpoints, new_endpoints)
with open('/workspace/src/render.rs', 'w') as f:
    f.write(content)
print("Done")
